window.NEURO = {"decks": [{"id": "inf", "title": "CNS, eye & ear infections"}], "questions": [{"id": "Q001", "deck": "inf", "topic": "Eye infection localization", "pages": [4], "page": 4, "ref": "slide-inf-4", "stem": "A painful eye has an epithelial defect overlying a white-gray stromal infiltrate with tissue loss. Which lesion is present?", "options": [{"text": "Infectious keratitis", "why": "Keratitis is the broader corneal inflammatory process that can underlie this lesion. The explicit epithelial defect and stromal tissue loss make corneal ulcer the more specific single best answer."}, {"text": "Anterior uveitis", "why": "Iris/ciliary inflammation causes ciliary redness, photophobia, and anterior chamber cells/flare rather than only superficial discharge."}, {"text": "Conjunctivitis", "why": "Conjunctival inflammation commonly causes redness, irritation, tearing, and discharge with relatively preserved vision; severe pain or photophobia suggests deeper disease."}, {"text": "Allergic conjunctivitis", "why": "Itching, watery discharge, and an allergic context favor noninfectious conjunctival inflammation, although symptoms overlap with infection."}, {"text": "Corneal ulcer", "why": "An ulcer combines epithelial breakdown with stromal involvement. Infection and inflammation can destroy corneal tissue and produce scarring or perforation."}], "answer": 4, "image": "figure-04.jpg"}, {"id": "Q002", "deck": "inf", "topic": "Eye infection localization", "pages": [5], "page": 5, "ref": "slide-inf-5", "stem": "A contact lens wearer develops pain, photophobia, reduced visual acuity, and a corneal infiltrate. Which anatomic diagnosis best fits?", "options": [{"text": "Retinitis", "why": "Retinal inflammation causes floaters, scotomas, or vision loss with posterior retinal lesions; it is not diagnosed solely from a red ocular surface."}, {"text": "Anterior uveitis", "why": "Iris/ciliary inflammation causes ciliary redness, photophobia, and anterior chamber cells/flare rather than only superficial discharge."}, {"text": "Conjunctivitis", "why": "Conjunctival inflammation commonly causes redness, irritation, tearing, and discharge with relatively preserved vision; severe pain or photophobia suggests deeper disease."}, {"text": "Infectious keratitis", "why": "The cornea is involved. Epithelial injury permits microbial invasion and an inflammatory response that can progress to ulceration and vision loss."}, {"text": "Allergic conjunctivitis", "why": "Itching, watery discharge, and an allergic context favor noninfectious conjunctival inflammation, although symptoms overlap with infection."}], "answer": 3, "image": null}, {"id": "Q003", "deck": "inf", "topic": "Eye infection localization", "pages": [6], "page": 6, "ref": "slide-inf-6", "stem": "A child has red conjunctivae, mild irritation, tearing, and discharge but no major photophobia or reduction in acuity. Which diagnosis best fits?", "options": [{"text": "Anterior uveitis", "why": "Iris/ciliary inflammation causes ciliary redness, photophobia, and anterior chamber cells/flare rather than only superficial discharge."}, {"text": "Retinitis", "why": "Retinal inflammation causes floaters, scotomas, or vision loss with posterior retinal lesions; it is not diagnosed solely from a red ocular surface."}, {"text": "Conjunctivitis", "why": "The symptoms localize to the conjunctival surface. Deeper pain, severe light sensitivity, or visual loss should trigger evaluation for corneal or intraocular disease."}, {"text": "Infectious keratitis", "why": "Corneal infection causes pain, photophobia, decreased acuity, and an infiltrate; it is more concerning for vision than routine superficial conjunctivitis."}, {"text": "Corneal ulcer", "why": "A corneal epithelial defect with underlying stromal infiltration/tissue loss is an ulcer; severe cases can scar, perforate, and threaten vision."}], "answer": 2, "image": null}, {"id": "Q004", "deck": "inf", "topic": "Eye infection localization", "pages": [8], "page": 8, "ref": "slide-inf-8", "stem": "An adult has a painful photophobic red eye with redness concentrated around the limbus. Slit-lamp examination shows inflammatory cells in the anterior chamber. Which diagnosis fits?", "options": [{"text": "Anterior uveitis", "why": "Anterior uveal inflammation affects the iris/ciliary body and produces ciliary injection and cells/flare. Infectious, autoimmune, and idiopathic causes are possible."}, {"text": "Conjunctivitis", "why": "Conjunctival inflammation commonly causes redness, irritation, tearing, and discharge with relatively preserved vision; severe pain or photophobia suggests deeper disease."}, {"text": "Allergic conjunctivitis", "why": "Itching, watery discharge, and an allergic context favor noninfectious conjunctival inflammation, although symptoms overlap with infection."}, {"text": "Infectious keratitis", "why": "Corneal infection causes pain, photophobia, decreased acuity, and an infiltrate; it is more concerning for vision than routine superficial conjunctivitis."}, {"text": "Retinitis", "why": "Retinal inflammation causes floaters, scotomas, or vision loss with posterior retinal lesions; it is not diagnosed solely from a red ocular surface."}], "answer": 0, "image": null}, {"id": "Q005", "deck": "inf", "topic": "Eye infection localization", "pages": [9], "page": 9, "ref": "slide-inf-9", "stem": "A severely immunocompromised patient develops floaters, a field scotoma, and retinal hemorrhagic necrosis. Which anatomic syndrome is present?", "options": [{"text": "Allergic conjunctivitis", "why": "Itching, watery discharge, and an allergic context favor noninfectious conjunctival inflammation, although symptoms overlap with infection."}, {"text": "Retinitis", "why": "Retinal damage explains posterior visual symptoms and funduscopic necrosis. Cytopathic viral injury can progress rapidly and threaten sight."}, {"text": "Corneal ulcer", "why": "A corneal epithelial defect with underlying stromal infiltration/tissue loss is an ulcer; severe cases can scar, perforate, and threaten vision."}, {"text": "Anterior uveitis", "why": "Iris/ciliary inflammation causes ciliary redness, photophobia, and anterior chamber cells/flare rather than only superficial discharge."}, {"text": "Conjunctivitis", "why": "Conjunctival inflammation commonly causes redness, irritation, tearing, and discharge with relatively preserved vision; severe pain or photophobia suggests deeper disease."}], "answer": 1, "image": null}, {"id": "Q006", "deck": "inf", "topic": "Eye infection localization", "pages": [6, 7], "page": 6, "ref": "slide-inf-6", "stem": "An atopic patient has bilateral itching, watery discharge, and seasonal recurrence without reduced acuity. Which diagnosis is most likely?", "options": [{"text": "Infectious keratitis", "why": "Corneal infection causes pain, photophobia, decreased acuity, and an infiltrate; it is more concerning for vision than routine superficial conjunctivitis."}, {"text": "Corneal ulcer", "why": "A corneal epithelial defect with underlying stromal infiltration/tissue loss is an ulcer; severe cases can scar, perforate, and threaten vision."}, {"text": "Retinitis", "why": "Retinal inflammation causes floaters, scotomas, or vision loss with posterior retinal lesions; it is not diagnosed solely from a red ocular surface."}, {"text": "Anterior uveitis", "why": "Iris/ciliary inflammation causes ciliary redness, photophobia, and anterior chamber cells/flare rather than only superficial discharge."}, {"text": "Allergic conjunctivitis", "why": "Prominent itching and seasonal recurrence favor allergy. Watery discharge alone is insufficient to distinguish allergic from viral conjunctivitis."}], "answer": 4, "image": null}, {"id": "Q007", "deck": "inf", "topic": "Eye infection localization", "pages": [4, 5, 6], "page": 4, "ref": "slide-inf-4", "stem": "A patient initially calls a red eye pink eye, but examination reveals marked photophobia and a corneal opacity. Which diagnosis warrants priority over uncomplicated conjunctivitis?", "options": [{"text": "Allergic conjunctivitis", "why": "Itching, watery discharge, and an allergic context favor noninfectious conjunctival inflammation, although symptoms overlap with infection."}, {"text": "Conjunctivitis", "why": "Conjunctival inflammation commonly causes redness, irritation, tearing, and discharge with relatively preserved vision; severe pain or photophobia suggests deeper disease."}, {"text": "Infectious keratitis", "why": "Corneal involvement, pain, and reduced visual function suggest sight-threatening keratitis rather than a routine superficial process. Urgent eye assessment is appropriate."}, {"text": "Anterior uveitis", "why": "Iris/ciliary inflammation causes ciliary redness, photophobia, and anterior chamber cells/flare rather than only superficial discharge."}, {"text": "Corneal ulcer", "why": "A corneal epithelial defect with underlying stromal infiltration/tissue loss is an ulcer; severe cases can scar, perforate, and threaten vision."}], "answer": 2, "image": null}, {"id": "Q008", "deck": "inf", "topic": "Eye pathogens", "pages": [4, 5], "page": 4, "ref": "slide-inf-4", "stem": "A contact lens wearer develops a rapidly progressive bacterial corneal ulcer. Culture grows an oxidase-positive gram-negative rod. Which organism is most likely?", "options": [{"text": "Fusarium species", "why": "Filamentous fungi can cause keratitis after vegetative trauma, often with feathery infiltrates; Fusarium is not a herpesvirus or bacterium."}, {"text": "Chlamydia trachomatis", "why": "Chlamydia can cause chronic follicular conjunctivitis and trachoma, with repeated inflammation leading to scarring; serovar and exposure context matter."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Pseudomonas aeruginosa", "why": "Contact lenses and water exposure increase concern for Pseudomonas bacterial keratitis. Its tissue-destructive infection can progress quickly."}, {"text": "Acanthamoeba species", "why": "Water exposure with contact lenses, severe pain out of proportion, and a ring infiltrate suggest amebic keratitis, including in otherwise healthy people."}], "answer": 3, "image": null}, {"id": "Q009", "deck": "inf", "topic": "Eye pathogens", "pages": [4, 5], "page": 4, "ref": "slide-inf-4", "stem": "A lens wearer rinses lenses in tap water and develops extreme corneal pain with a ring infiltrate. Which pathogen is particularly concerning?", "options": [{"text": "Adenovirus", "why": "This common cause of contagious watery conjunctivitis can accompany pharyngitis and preauricular nodes; it is not a bacterium producing a Gram stain isolate."}, {"text": "Acanthamoeba species", "why": "Acanthamoeba keratitis is strongly associated with water-contaminated lens practices. Severe pain and a ring infiltrate are clues, but not independently diagnostic."}, {"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus can cause conjunctivitis, keratitis, otitis media, and meningitis rather than being restricted to one site."}, {"text": "Pseudomonas aeruginosa", "why": "This water-associated gram-negative bacterium is important in contact lens-associated bacterial keratitis and otitis externa; it can cause rapid corneal destruction."}, {"text": "Corynebacterium diphtheriae", "why": "This organism is a less common cause of membranous conjunctivitis in the appropriate clinical context, not the usual viral pink-eye agent."}], "answer": 1, "image": null}, {"id": "Q010", "deck": "inf", "topic": "Eye pathogens", "pages": [4, 5], "page": 4, "ref": "slide-inf-4", "stem": "A recurrent unilateral corneal epithelial lesion branches in a dendritic pattern with terminal bulbs. Which agent is favored?", "options": [{"text": "Herpes simplex virus", "why": "Dendritic epithelial keratitis is characteristic of HSV. Recurrent corneal infection differs from adenoviral conjunctival inflammation."}, {"text": "Adenovirus", "why": "This common cause of contagious watery conjunctivitis can accompany pharyngitis and preauricular nodes; it is not a bacterium producing a Gram stain isolate."}, {"text": "Candida species", "why": "Yeasts can cause ocular infection, especially with a compromised cornea or systemic candidemia, and can also produce otomycosis or CNS invasion."}, {"text": "Acanthamoeba species", "why": "Water exposure with contact lenses, severe pain out of proportion, and a ring infiltrate suggest amebic keratitis, including in otherwise healthy people."}, {"text": "Staphylococcus aureus", "why": "This skin-associated gram-positive organism can cause bacterial conjunctivitis, keratitis, and otitis externa; culture/context distinguish it from other bacteria."}], "answer": 0, "image": null}, {"id": "Q011", "deck": "inf", "topic": "Eye pathogens", "pages": [4], "page": 4, "ref": "slide-inf-4", "stem": "After plant-related eye trauma, a patient develops a feathery corneal ulcer; culture identifies Fusarium. What is the causative organism?", "options": [{"text": "Fusarium species", "why": "Vegetative trauma can introduce filamentous fungi. Fusarium and Aspergillus are important fungal ulcer pathogens."}, {"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus can cause conjunctivitis, keratitis, otitis media, and meningitis rather than being restricted to one site."}, {"text": "Chlamydia trachomatis", "why": "Chlamydia can cause chronic follicular conjunctivitis and trachoma, with repeated inflammation leading to scarring; serovar and exposure context matter."}, {"text": "Candida species", "why": "Yeasts can cause ocular infection, especially with a compromised cornea or systemic candidemia, and can also produce otomycosis or CNS invasion."}, {"text": "Staphylococcus aureus", "why": "This skin-associated gram-positive organism can cause bacterial conjunctivitis, keratitis, and otitis externa; culture/context distinguish it from other bacteria."}], "answer": 0, "image": null}, {"id": "Q012", "deck": "inf", "topic": "Eye pathogens", "pages": [4, 5], "page": 4, "ref": "slide-inf-4", "stem": "A corneal culture shows a mold with septate acute-angle branching hyphae in a patient with fungal keratitis. Which organism fits?", "options": [{"text": "Pseudomonas aeruginosa", "why": "This water-associated gram-negative bacterium is important in contact lens-associated bacterial keratitis and otitis externa; it can cause rapid corneal destruction."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Aspergillus species", "why": "Aspergillus is a filamentous mold capable of corneal infection. Its invasive systemic manifestations differ from isolated ocular infection."}, {"text": "Staphylococcus aureus", "why": "This skin-associated gram-positive organism can cause bacterial conjunctivitis, keratitis, and otitis externa; culture/context distinguish it from other bacteria."}, {"text": "Acanthamoeba species", "why": "Water exposure with contact lenses, severe pain out of proportion, and a ring infiltrate suggest amebic keratitis, including in otherwise healthy people."}], "answer": 2, "image": null}, {"id": "Q013", "deck": "inf", "topic": "Eye pathogens", "pages": [5], "page": 5, "ref": "slide-inf-5", "stem": "A patient with a chronically compromised ocular surface develops keratitis with budding yeast and pseudohyphae on microscopy. Which genus is likely?", "options": [{"text": "Fusarium species", "why": "Filamentous fungi can cause keratitis after vegetative trauma, often with feathery infiltrates; Fusarium is not a herpesvirus or bacterium."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Adenovirus", "why": "This common cause of contagious watery conjunctivitis can accompany pharyngitis and preauricular nodes; it is not a bacterium producing a Gram stain isolate."}, {"text": "Cytomegalovirus", "why": "CMV causes necrotizing retinitis particularly with profound cellular immunosuppression; it is a herpesvirus, not a protozoan."}, {"text": "Candida species", "why": "Candida can infect a damaged cornea and is distinguished from filamentous molds by yeast/pseudohyphal morphology."}], "answer": 4, "image": null}, {"id": "Q014", "deck": "inf", "topic": "Eye pathogens", "pages": [6], "page": 6, "ref": "slide-inf-6", "stem": "Several students develop watery pink eyes during a respiratory outbreak, with preauricular nodes and mild pharyngitis. Which agent is most likely?", "options": [{"text": "Haemophilus influenzae", "why": "This bacterium is relevant to conjunctivitis and otitis media; nontypeable strains differ from encapsulated type b invasive disease."}, {"text": "Adenovirus", "why": "Adenovirus is a common viral conjunctivitis cause and can produce pharyngoconjunctival illness. Discharge character supports but does not prove etiology."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Cytomegalovirus", "why": "CMV causes necrotizing retinitis particularly with profound cellular immunosuppression; it is a herpesvirus, not a protozoan."}, {"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}], "answer": 1, "image": null}, {"id": "Q015", "deck": "inf", "topic": "Eye pathogens", "pages": [6], "page": 6, "ref": "slide-inf-6", "stem": "A patient has chronic follicular conjunctivitis, and testing identifies an obligate intracellular bacterium associated with trachoma. Which organism is responsible?", "options": [{"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus can cause conjunctivitis, keratitis, otitis media, and meningitis rather than being restricted to one site."}, {"text": "Fusarium species", "why": "Filamentous fungi can cause keratitis after vegetative trauma, often with feathery infiltrates; Fusarium is not a herpesvirus or bacterium."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Chlamydia trachomatis", "why": "Repeated trachoma infection can scar conjunctiva and turn eyelashes inward, injuring the cornea. Trachoma serovars differ from typical genital inclusion-conjunctivitis serovars."}, {"text": "Cytomegalovirus", "why": "CMV causes necrotizing retinitis particularly with profound cellular immunosuppression; it is a herpesvirus, not a protozoan."}], "answer": 3, "image": null}, {"id": "Q016", "deck": "inf", "topic": "Eye pathogens", "pages": [6], "page": 6, "ref": "slide-inf-6", "stem": "A conjunctivitis isolate is catalase-positive and coagulase-positive gram-positive cocci in clusters. Which listed organism fits?", "options": [{"text": "Acanthamoeba species", "why": "Water exposure with contact lenses, severe pain out of proportion, and a ring infiltrate suggest amebic keratitis, including in otherwise healthy people."}, {"text": "Adenovirus", "why": "This common cause of contagious watery conjunctivitis can accompany pharyngitis and preauricular nodes; it is not a bacterium producing a Gram stain isolate."}, {"text": "Corynebacterium diphtheriae", "why": "This organism is a less common cause of membranous conjunctivitis in the appropriate clinical context, not the usual viral pink-eye agent."}, {"text": "Staphylococcus aureus", "why": "S. aureus is a bacterial cause of conjunctivitis and can also invade cornea. Morphology and coagulase positivity distinguish it from pneumococci."}, {"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}], "answer": 3, "image": null}, {"id": "Q017", "deck": "inf", "topic": "Eye pathogens", "pages": [4, 6], "page": 4, "ref": "slide-inf-4", "stem": "A corneal or conjunctival bacterial isolate consists of encapsulated gram-positive diplococci. Which listed pathogen fits?", "options": [{"text": "Aspergillus species", "why": "This mold can cause fungal keratitis, otomycosis, or angioinvasive CNS disease in susceptible hosts."}, {"text": "Staphylococcus aureus", "why": "This skin-associated gram-positive organism can cause bacterial conjunctivitis, keratitis, and otitis externa; culture/context distinguish it from other bacteria."}, {"text": "Corynebacterium diphtheriae", "why": "This organism is a less common cause of membranous conjunctivitis in the appropriate clinical context, not the usual viral pink-eye agent."}, {"text": "Streptococcus pneumoniae", "why": "Pneumococcus can cause infection at ocular, middle-ear, and meningeal sites. Its morphology differs from staphylococcal clusters."}, {"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}], "answer": 3, "image": null}, {"id": "Q018", "deck": "inf", "topic": "Eye pathogens", "pages": [6, 14], "page": 6, "ref": "slide-inf-6", "stem": "A child has purulent conjunctivitis together with acute otitis media. Culture identifies a small gram-negative coccobacillus, often nontypeable. Which organism is associated?", "options": [{"text": "Staphylococcus aureus", "why": "This skin-associated gram-positive organism can cause bacterial conjunctivitis, keratitis, and otitis externa; culture/context distinguish it from other bacteria."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Candida species", "why": "Yeasts can cause ocular infection, especially with a compromised cornea or systemic candidemia, and can also produce otomycosis or CNS invasion."}, {"text": "Haemophilus influenzae", "why": "Nontypeable H. influenzae is important in conjunctivitis-otitis syndrome. This is distinct from the Hib capsule targeted by the type b vaccine."}, {"text": "Cytomegalovirus", "why": "CMV causes necrotizing retinitis particularly with profound cellular immunosuppression; it is a herpesvirus, not a protozoan."}], "answer": 3, "image": null}, {"id": "Q019", "deck": "inf", "topic": "Eye pathogens", "pages": [6], "page": 6, "ref": "slide-inf-6", "stem": "A patient from an undervaccinated community has conjunctivitis with an adherent membrane and a toxigenic coryneform isolate. Which organism is a listed cause?", "options": [{"text": "Chlamydia trachomatis", "why": "Chlamydia can cause chronic follicular conjunctivitis and trachoma, with repeated inflammation leading to scarring; serovar and exposure context matter."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}, {"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus can cause conjunctivitis, keratitis, otitis media, and meningitis rather than being restricted to one site."}, {"text": "Corynebacterium diphtheriae", "why": "Diphtheria can involve conjunctiva with membranous inflammation. It is not a usual cause of ordinary viral watery conjunctivitis."}], "answer": 4, "image": null}, {"id": "Q020", "deck": "inf", "topic": "Eye pathogens", "pages": [8], "page": 8, "ref": "slide-inf-8", "stem": "A patient has recurrent unilateral anterior uveitis and evidence of herpetic ocular infection. Which virus listed in the deck is most associated?", "options": [{"text": "Aspergillus species", "why": "This mold can cause fungal keratitis, otomycosis, or angioinvasive CNS disease in susceptible hosts."}, {"text": "Herpes simplex virus", "why": "HSV can cause anterior uveal inflammation, often alongside corneal findings. Not all uveitis is infectious, so systemic/immune alternatives remain important."}, {"text": "Candida species", "why": "Yeasts can cause ocular infection, especially with a compromised cornea or systemic candidemia, and can also produce otomycosis or CNS invasion."}, {"text": "Adenovirus", "why": "This common cause of contagious watery conjunctivitis can accompany pharyngitis and preauricular nodes; it is not a bacterium producing a Gram stain isolate."}, {"text": "Cytomegalovirus", "why": "CMV causes necrotizing retinitis particularly with profound cellular immunosuppression; it is a herpesvirus, not a protozoan."}], "answer": 1, "image": null}, {"id": "Q021", "deck": "inf", "topic": "Eye pathogens", "pages": [8, 9], "page": 8, "ref": "slide-inf-8", "stem": "An adult with advanced HIV and CD4 count of 24/µL develops floaters and hemorrhagic necrotizing retinal lesions. Which pathogen is most likely?", "options": [{"text": "Cytomegalovirus", "why": "Profound cellular immunodeficiency predisposes to CMV retinitis. Ocular examination is central; a blood viral load alone does not establish the retinal diagnosis."}, {"text": "Haemophilus influenzae", "why": "This bacterium is relevant to conjunctivitis and otitis media; nontypeable strains differ from encapsulated type b invasive disease."}, {"text": "Chlamydia trachomatis", "why": "Chlamydia can cause chronic follicular conjunctivitis and trachoma, with repeated inflammation leading to scarring; serovar and exposure context matter."}, {"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}, {"text": "Corynebacterium diphtheriae", "why": "This organism is a less common cause of membranous conjunctivitis in the appropriate clinical context, not the usual viral pink-eye agent."}], "answer": 0, "image": null}, {"id": "Q022", "deck": "inf", "topic": "Eye pathogens", "pages": [8, 9], "page": 8, "ref": "slide-inf-8", "stem": "A focal white retinal inflammatory lesion adjacent to an old pigmented scar is associated with posterior uveitis. Which pathogen is favored?", "options": [{"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}, {"text": "Aspergillus species", "why": "This mold can cause fungal keratitis, otomycosis, or angioinvasive CNS disease in susceptible hosts."}, {"text": "Toxoplasma gondii", "why": "Ocular toxoplasmosis commonly produces retinochoroiditis. The slide's suggestion that Toxoplasma is a rare fungal cause is incorrect: it is a protozoan and an important ocular pathogen."}, {"text": "Corynebacterium diphtheriae", "why": "This organism is a less common cause of membranous conjunctivitis in the appropriate clinical context, not the usual viral pink-eye agent."}, {"text": "Cytomegalovirus", "why": "CMV causes necrotizing retinitis particularly with profound cellular immunosuppression; it is a herpesvirus, not a protozoan."}], "answer": 2, "image": null}, {"id": "Q023", "deck": "inf", "topic": "Conjunctivitis interpretation", "pages": [6, 7], "page": 6, "ref": "slide-inf-6", "stem": "Which conclusion is justified by mucopurulent discharge and eyelid matting?", "options": [{"text": "They prove that the retina is necrotic", "why": "Surface discharge does not establish retinitis."}, {"text": "They increase the likelihood of bacterial conjunctivitis without proving it", "why": "Symptoms overlap across causes; no single discharge finding reliably distinguishes bacterial from viral disease."}, {"text": "They make pain and visual acuity irrelevant", "why": "Pain, photophobia, and reduced vision remain important red flags."}, {"text": "They definitively exclude all viral disease", "why": "Viral and bacterial findings can overlap, so this is too absolute."}, {"text": "They prove that the uvea is infected", "why": "Uveitis requires intraocular evidence, not discharge alone."}], "answer": 1, "image": null}, {"id": "Q024", "deck": "inf", "topic": "Corneal tissue injury", "pages": [4, 5], "page": 4, "ref": "slide-inf-4", "stem": "Why can untreated infectious keratitis leave permanent visual impairment?", "options": [{"text": "Keratitis affects only the external eyelid skin", "why": "The affected tissue is the cornea itself."}, {"text": "Only the lens determines visual clarity", "why": "The cornea is a major transparent refracting structure."}, {"text": "The cornea normally regenerates every damaged layer without scarring", "why": "Significant stromal injury may heal with persistent opacity."}, {"text": "Corneal inflammation is always confined to harmless tear-film changes", "why": "Infection can invade epithelium/stroma and threaten structure."}, {"text": "Microbial injury and host inflammation can ulcerate and scar the cornea", "why": "Loss of transparent stromal architecture impairs optics; severe tissue loss can progress to perforation."}], "answer": 4, "image": null}, {"id": "Q025", "deck": "inf", "topic": "Uveal anatomy and causes", "pages": [8], "page": 8, "ref": "slide-inf-8", "stem": "Which structures make up the uveal tract?", "options": [{"text": "Retina, lacrimal gland, and pupil opening", "why": "These are not the three uveal structures."}, {"text": "Trabecular meshwork, Schlemm canal, and vitreous", "why": "These do not constitute the uveal tract."}, {"text": "Lens, optic nerve, and eyelid", "why": "These do not define the vascular uveal layer."}, {"text": "Cornea, conjunctiva, and sclera", "why": "These are surface/outer-coat structures rather than the uveal triad."}, {"text": "Iris, ciliary body, and choroid", "why": "Uveitis can affect anterior, intermediate, posterior, or all uveal compartments depending on its pattern."}], "answer": 4, "image": null}, {"id": "Q026", "deck": "inf", "topic": "Uveitis differential", "pages": [8], "page": 8, "ref": "slide-inf-8", "stem": "A patient has uveitis but no pathogen has been demonstrated. Which statement is most accurate?", "options": [{"text": "Autoimmune disease cannot affect intraocular tissues", "why": "Systemic immune disorders can cause uveitis."}, {"text": "Every uveitis case is bacterial", "why": "The deck specifically includes noninfectious and viral/protozoal categories."}, {"text": "Floaters always prove CMV", "why": "Floaters are nonspecific and can arise from multiple posterior disorders."}, {"text": "Immune-mediated and idiopathic disease are major alternative categories", "why": "Uveitis is an inflammatory syndrome, not proof of infection. Granulomatous versus nongranulomatous morphology and systemic context help narrow causes."}, {"text": "Bilateral involvement excludes infection", "why": "Infectious uveitis may be unilateral or bilateral depending on cause and host."}], "answer": 3, "image": null}, {"id": "Q027", "deck": "inf", "topic": "Retinal tissue injury", "pages": [9], "page": 9, "ref": "slide-inf-9", "stem": "Which mechanism contributes to rapidly progressive viral retinitis?", "options": [{"text": "Only conjunctival hyperemia without tissue injury", "why": "Retinitis involves posterior retinal tissue."}, {"text": "Purely external canal blockage", "why": "This is an auditory conductive mechanism."}, {"text": "Only a mechanical obstruction in the tear duct", "why": "That does not explain retinal necrosis."}, {"text": "Direct viral cytopathic injury with retinal inflammation and necrosis", "why": "Damage to neural retina can produce scotomas and irreversible vision loss. Ocular localization and organism testing guide care."}, {"text": "Only lens protein aggregation", "why": "That causes cataract rather than retinitis."}], "answer": 3, "image": null}, {"id": "Q028", "deck": "inf", "topic": "Ear infection localization", "pages": [11, 12], "page": 11, "ref": "slide-inf-11", "stem": "A swimmer has severe ear pain that increases when the tragus is pressed. The canal is swollen and erythematous, without a bulging drum. Which diagnosis fits?", "options": [{"text": "Acute otitis externa", "why": "Water exposure and canal barrier disruption favor AOE. Tragal/auricular tenderness localizes the process to the external canal rather than the middle ear."}, {"text": "Otomycosis", "why": "Fungal external canal disease often causes itching, debris, and discharge; Aspergillus and Candida are important organisms."}, {"text": "Necrotizing otitis externa", "why": "Severe persistent otalgia with granulation tissue, especially in a diabetic/immunocompromised host, raises concern for invasive canal/skull-base infection."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid without acute infectious symptoms is OME; fluid alone does not establish acute otitis media."}, {"text": "Acute otitis media", "why": "A bulging poorly mobile tympanic membrane with acute symptoms and middle-ear fluid supports AOM, not simply canal skin inflammation."}], "answer": 0, "image": null}, {"id": "Q029", "deck": "inf", "topic": "Ear infection localization", "pages": [13, 14], "page": 13, "ref": "slide-inf-13", "stem": "A febrile toddler has deep otalgia and a bulging opaque poorly mobile tympanic membrane. Pulling the auricle does not markedly worsen pain. Which diagnosis fits?", "options": [{"text": "Otitis media with effusion", "why": "Middle-ear fluid without acute infectious symptoms is OME; fluid alone does not establish acute otitis media."}, {"text": "Acute otitis externa", "why": "Inflamed edematous external canal with pain on tragal pressure or auricle movement suggests AOE; canal obstruction can cause conductive loss."}, {"text": "Necrotizing otitis externa", "why": "Severe persistent otalgia with granulation tissue, especially in a diabetic/immunocompromised host, raises concern for invasive canal/skull-base infection."}, {"text": "Otomycosis", "why": "Fungal external canal disease often causes itching, debris, and discharge; Aspergillus and Candida are important organisms."}, {"text": "Acute otitis media", "why": "Middle-ear fluid and pressure produce bulging and reduced mobility. Acute symptoms distinguish AOM from uncomplicated residual effusion."}], "answer": 4, "image": null}, {"id": "Q030", "deck": "inf", "topic": "Ear infection localization", "pages": [11, 12], "page": 11, "ref": "slide-inf-11", "stem": "An immunocompromised patient has prominent canal itching and cottony fungal debris. Which diagnosis is most likely?", "options": [{"text": "Necrotizing otitis externa", "why": "Severe persistent otalgia with granulation tissue, especially in a diabetic/immunocompromised host, raises concern for invasive canal/skull-base infection."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid without acute infectious symptoms is OME; fluid alone does not establish acute otitis media."}, {"text": "Acute otitis externa", "why": "Inflamed edematous external canal with pain on tragal pressure or auricle movement suggests AOE; canal obstruction can cause conductive loss."}, {"text": "Acute otitis media", "why": "A bulging poorly mobile tympanic membrane with acute symptoms and middle-ear fluid supports AOM, not simply canal skin inflammation."}, {"text": "Otomycosis", "why": "Fungi can cause external canal infection, particularly in chronic or predisposed settings. Aspergillus and Candida are listed organisms."}], "answer": 4, "image": null}, {"id": "Q031", "deck": "inf", "topic": "Ear infection localization", "pages": [13, 14], "page": 13, "ref": "slide-inf-13", "stem": "A child has fluid behind the drum after a respiratory illness but no acute pain, fever, or drum bulging. Which diagnosis is more precise than AOM?", "options": [{"text": "Otitis media with effusion", "why": "Effusion can persist without acute infection. A red drum or fluid alone does not establish acute bacterial otitis media."}, {"text": "Necrotizing otitis externa", "why": "Severe persistent otalgia with granulation tissue, especially in a diabetic/immunocompromised host, raises concern for invasive canal/skull-base infection."}, {"text": "Acute otitis media", "why": "A bulging poorly mobile tympanic membrane with acute symptoms and middle-ear fluid supports AOM, not simply canal skin inflammation."}, {"text": "Otomycosis", "why": "Fungal external canal disease often causes itching, debris, and discharge; Aspergillus and Candida are important organisms."}, {"text": "Acute otitis externa", "why": "Inflamed edematous external canal with pain on tragal pressure or auricle movement suggests AOE; canal obstruction can cause conductive loss."}], "answer": 0, "image": null}, {"id": "Q032", "deck": "inf", "topic": "Ear infection localization", "pages": [11, 12], "page": 11, "ref": "slide-inf-11", "stem": "An older diabetic patient has severe persistent nocturnal ear pain, granulation in the canal, and a new facial palsy. Which invasive extension must be considered?", "options": [{"text": "Otomycosis", "why": "Fungal external canal disease often causes itching, debris, and discharge; Aspergillus and Candida are important organisms."}, {"text": "Acute otitis media", "why": "A bulging poorly mobile tympanic membrane with acute symptoms and middle-ear fluid supports AOM, not simply canal skin inflammation."}, {"text": "Otitis media with effusion", "why": "Middle-ear fluid without acute infectious symptoms is OME; fluid alone does not establish acute otitis media."}, {"text": "Acute otitis externa", "why": "Inflamed edematous external canal with pain on tragal pressure or auricle movement suggests AOE; canal obstruction can cause conductive loss."}, {"text": "Necrotizing otitis externa", "why": "This supplemental application distinguishes a dangerous invasive infection from routine AOE. Pseudomonas is a characteristic cause in the appropriate host."}], "answer": 4, "image": null}, {"id": "Q033", "deck": "inf", "topic": "Ear pathogens", "pages": [12], "page": 12, "ref": "slide-inf-12", "stem": "A swimmer with otitis externa has an oxidase-positive gram-negative rod isolated from canal drainage. Which organism is most likely?", "options": [{"text": "Pseudomonas aeruginosa", "why": "Moisture-rich canal conditions favor Pseudomonas. This is a classic external-ear pathogen rather than one of the usual encapsulated respiratory AOM bacteria."}, {"text": "Nontypeable Haemophilus influenzae", "why": "This is a common modern bacterial AOM pathogen and can accompany purulent conjunctivitis; prevalence varies by population."}, {"text": "Aspergillus species", "why": "Filamentous molds are common otomycosis agents, with itching and fungal debris rather than the usual bulging AOM drum."}, {"text": "Staphylococcus aureus", "why": "Skin barrier disruption can permit staphylococcal external canal infection; it is also relevant to ocular and abscess disease."}, {"text": "Moraxella catarrhalis", "why": "This gram-negative diplococcus is an important pediatric AOM pathogen, distinct from the usual Pseudomonas swimmer's-ear pattern."}], "answer": 0, "image": null}, {"id": "Q034", "deck": "inf", "topic": "Ear pathogens", "pages": [12], "page": 12, "ref": "slide-inf-12", "stem": "After repeated cotton-swab trauma, a patient develops AOE with coagulase-positive gram-positive cocci in clusters. Which organism fits?", "options": [{"text": "Streptococcus pneumoniae", "why": "Pneumococcus remains an important AOM organism despite changes after vaccination; it also causes invasive meningitis."}, {"text": "Moraxella catarrhalis", "why": "This gram-negative diplococcus is an important pediatric AOM pathogen, distinct from the usual Pseudomonas swimmer's-ear pattern."}, {"text": "Staphylococcus aureus", "why": "Disruption of canal skin permits S. aureus infection. Mechanical trauma, hearing aids, and eczema are additional barrier-related risk factors."}, {"text": "Aspergillus species", "why": "Filamentous molds are common otomycosis agents, with itching and fungal debris rather than the usual bulging AOM drum."}, {"text": "Candida species", "why": "Yeast can cause fungal otitis externa, especially with altered canal conditions or host defenses."}], "answer": 2, "image": null}, {"id": "Q035", "deck": "inf", "topic": "Ear pathogens", "pages": [11, 12], "page": 11, "ref": "slide-inf-11", "stem": "An itchy ear contains filamentous fungal debris, and microscopy/culture shows Aspergillus. Which pathogen is responsible?", "options": [{"text": "Pseudomonas aeruginosa", "why": "A water-associated gram-negative rod is a major cause of bacterial otitis externa and severe invasive external-ear infection."}, {"text": "Aspergillus species", "why": "Aspergillus is a major mold cause of otomycosis. Candida is an alternative yeast cause but does not match the identified mold."}, {"text": "Staphylococcus aureus", "why": "Skin barrier disruption can permit staphylococcal external canal infection; it is also relevant to ocular and abscess disease."}, {"text": "Respiratory syncytial virus", "why": "Viral respiratory infection can impair Eustachian tube function and predispose to AOM; it is not a bacterial culture isolate."}, {"text": "Rhinovirus", "why": "Upper respiratory infection can promote Eustachian dysfunction and middle-ear disease without being one of the bacterial AOM pathogens."}], "answer": 1, "image": null}, {"id": "Q036", "deck": "inf", "topic": "Ear pathogens", "pages": [11, 12], "page": 11, "ref": "slide-inf-11", "stem": "An ear-canal fungal isolate shows budding yeast and pseudohyphae. Which organism best fits?", "options": [{"text": "Candida species", "why": "Candida can produce otomycosis, especially with chronic local disruption or host predisposition."}, {"text": "Rhinovirus", "why": "Upper respiratory infection can promote Eustachian dysfunction and middle-ear disease without being one of the bacterial AOM pathogens."}, {"text": "Adenovirus", "why": "This respiratory/conjunctival virus can contribute to upper-airway inflammation and predispose to middle-ear disease."}, {"text": "Aspergillus species", "why": "Filamentous molds are common otomycosis agents, with itching and fungal debris rather than the usual bulging AOM drum."}, {"text": "Moraxella catarrhalis", "why": "This gram-negative diplococcus is an important pediatric AOM pathogen, distinct from the usual Pseudomonas swimmer's-ear pattern."}], "answer": 0, "image": null}, {"id": "Q037", "deck": "inf", "topic": "Ear pathogens", "pages": [14], "page": 14, "ref": "slide-inf-14", "stem": "A child with AOM and conjunctivitis has a nontypeable small gram-negative coccobacillus. Which organism is most likely?", "options": [{"text": "Nontypeable Haemophilus influenzae", "why": "Nontypeable H. influenzae is common in AOM and conjunctivitis-otitis syndrome. Ranking it as universally the leading cause would overstate cohort-dependent epidemiology."}, {"text": "Streptococcus pneumoniae", "why": "Pneumococcus remains an important AOM organism despite changes after vaccination; it also causes invasive meningitis."}, {"text": "Moraxella catarrhalis", "why": "This gram-negative diplococcus is an important pediatric AOM pathogen, distinct from the usual Pseudomonas swimmer's-ear pattern."}, {"text": "Aspergillus species", "why": "Filamentous molds are common otomycosis agents, with itching and fungal debris rather than the usual bulging AOM drum."}, {"text": "Rhinovirus", "why": "Upper respiratory infection can promote Eustachian dysfunction and middle-ear disease without being one of the bacterial AOM pathogens."}], "answer": 0, "image": null}, {"id": "Q038", "deck": "inf", "topic": "Ear pathogens", "pages": [14], "page": 14, "ref": "slide-inf-14", "stem": "A child with AOM has an oxidase-positive gram-negative diplococcus identified as Moraxella. Which agent fits?", "options": [{"text": "Respiratory syncytial virus", "why": "Viral respiratory infection can impair Eustachian tube function and predispose to AOM; it is not a bacterial culture isolate."}, {"text": "Rhinovirus", "why": "Upper respiratory infection can promote Eustachian dysfunction and middle-ear disease without being one of the bacterial AOM pathogens."}, {"text": "Nontypeable Haemophilus influenzae", "why": "This is a common modern bacterial AOM pathogen and can accompany purulent conjunctivitis; prevalence varies by population."}, {"text": "Pseudomonas aeruginosa", "why": "A water-associated gram-negative rod is a major cause of bacterial otitis externa and severe invasive external-ear infection."}, {"text": "Moraxella catarrhalis", "why": "M. catarrhalis is a common respiratory-colonizing pediatric AOM organism. It should not be confused with meningococcal invasive disease solely because both are gram-negative diplococci."}], "answer": 4, "image": null}, {"id": "Q039", "deck": "inf", "topic": "Ear pathogens", "pages": [14], "page": 14, "ref": "slide-inf-14", "stem": "An AOM isolate consists of optochin-sensitive encapsulated gram-positive diplococci. Which agent fits?", "options": [{"text": "Streptococcus pneumoniae", "why": "Pneumococcus remains an important bacterial middle-ear pathogen and can spread or cause invasive disease in susceptible settings."}, {"text": "Moraxella catarrhalis", "why": "This gram-negative diplococcus is an important pediatric AOM pathogen, distinct from the usual Pseudomonas swimmer's-ear pattern."}, {"text": "Nontypeable Haemophilus influenzae", "why": "This is a common modern bacterial AOM pathogen and can accompany purulent conjunctivitis; prevalence varies by population."}, {"text": "Adenovirus", "why": "This respiratory/conjunctival virus can contribute to upper-airway inflammation and predispose to middle-ear disease."}, {"text": "Respiratory syncytial virus", "why": "Viral respiratory infection can impair Eustachian tube function and predispose to AOM; it is not a bacterial culture isolate."}], "answer": 0, "image": null}, {"id": "Q040", "deck": "inf", "topic": "Ear pathogens", "pages": [14], "page": 14, "ref": "slide-inf-14", "stem": "During bronchiolitis caused by RSV, a toddler develops Eustachian dysfunction and secondary AOM. Which viral contributor is present?", "options": [{"text": "Candida species", "why": "Yeast can cause fungal otitis externa, especially with altered canal conditions or host defenses."}, {"text": "Adenovirus", "why": "This respiratory/conjunctival virus can contribute to upper-airway inflammation and predispose to middle-ear disease."}, {"text": "Moraxella catarrhalis", "why": "This gram-negative diplococcus is an important pediatric AOM pathogen, distinct from the usual Pseudomonas swimmer's-ear pattern."}, {"text": "Aspergillus species", "why": "Filamentous molds are common otomycosis agents, with itching and fungal debris rather than the usual bulging AOM drum."}, {"text": "Respiratory syncytial virus", "why": "RSV is one of the respiratory viruses listed as predisposing contributors. The viral trigger and any subsequent bacterial isolate are different components of the process."}], "answer": 4, "image": null}, {"id": "Q041", "deck": "inf", "topic": "External ear pathogenesis", "pages": [12], "page": 12, "ref": "slide-inf-12", "stem": "Which combination predisposes to acute otitis externa?", "options": [{"text": "Only obstruction of the Eustachian tube with an intact canal", "why": "That is a middle-ear mechanism rather than the characteristic canal pathway."}, {"text": "Only hematogenous seeding of the meninges", "why": "That is a CNS infectious route."}, {"text": "Only HSV latency in the temporal lobe", "why": "That does not define routine swimmer’s ear."}, {"text": "Retained moisture plus disrupted canal epithelium", "why": "Swimming, excessive cleaning, hearing aids, and eczema can compromise the protective canal environment and permit microbial growth."}, {"text": "Only pressure in the subarachnoid space", "why": "That does not explain canal skin inflammation."}], "answer": 3, "image": null}, {"id": "Q042", "deck": "inf", "topic": "Middle-ear pathogenesis", "pages": [13, 14], "page": 13, "ref": "slide-inf-13", "stem": "Which sequence best explains AOM after an upper respiratory infection?", "options": [{"text": "External canal abrasion, tragal tenderness, normal middle-ear pressure", "why": "That better describes AOE."}, {"text": "Corneal epithelial breakdown, stromal infection, scarring", "why": "That is an ocular keratitis pathway."}, {"text": "Retrograde axonal transport from a bite", "why": "That is a rabies route."}, {"text": "A retinal scar followed by toxoplasma reactivation", "why": "That is an ocular posterior-infection pattern."}, {"text": "Eustachian dysfunction, middle-ear fluid stasis, microbial growth, increased pressure", "why": "Fluid and pressure behind the drum cause pain, bulging, and impaired vibration. Young Eustachian tube anatomy and airway inflammation increase susceptibility."}], "answer": 4, "image": null}, {"id": "Q043", "deck": "inf", "topic": "Ear examination", "pages": [13], "page": 13, "ref": "slide-inf-13", "stem": "What does reduced tympanic membrane mobility on pneumatic otoscopy suggest in a child with a bulging drum?", "options": [{"text": "Middle-ear effusion limiting membrane movement", "why": "Fluid and pressure reduce drum mobility. Together with acute bulging and symptoms, this supports AOM."}, {"text": "Only a viral meningeal syndrome", "why": "Meningitis is not established by drum mobility."}, {"text": "Only retinal inflammation", "why": "This is an otoscopic finding."}, {"text": "Definite cochlear hair-cell destruction", "why": "Mobility is a mechanical middle-ear finding, not a direct cochlear test."}, {"text": "A normal fluid-free middle ear in every case", "why": "Effusion is a central explanation for the reduced movement."}], "answer": 0, "image": null}, {"id": "Q044", "deck": "inf", "topic": "Ear hearing loss", "pages": [11, 13], "page": 11, "ref": "slide-inf-11", "stem": "Why can both severe AOE and AOM reduce hearing?", "options": [{"text": "Both can impair mechanical sound transmission, at different sites", "why": "Canal edema/debris obstructs AOE transmission, while middle-ear fluid impairs drum/ossicular motion in AOM, producing conductive loss."}, {"text": "Both eliminate all bone conduction immediately", "why": "Bone conduction can remain relatively preserved in isolated conductive disease."}, {"text": "Hearing changes prove that the drum cannot be involved", "why": "Middle-ear fluid and drum mechanics directly affect hearing."}, {"text": "Both necessarily destroy the cochlear nerve", "why": "Conductive mechanisms do not require neural destruction."}, {"text": "Both always cause bilateral cortical deafness", "why": "The typical local processes do not imply bilateral cortex injury."}], "answer": 0, "image": null}, {"id": "Q045", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 19], "page": 16, "ref": "slide-inf-16", "stem": "An adult develops acute fever, headache, photophobia, and neck stiffness with relatively preserved cognition. Which syndrome is most directly suggested?", "options": [{"text": "Encephalitis", "why": "Brain parenchymal inflammation causes altered mental status, seizures, focal findings, and supportive CSF/MRI/EEG evidence rather than only meningeal irritation."}, {"text": "Epidural abscess", "why": "An intracranial epidural collection lies between skull and dura; this is anatomically distinct from subdural pus or an intraparenchymal abscess."}, {"text": "Acute disseminated encephalomyelitis", "why": "ADEM is an immune-mediated multifocal demyelinating syndrome often after infection, with encephalopathy and predominantly white-matter lesions; it is not direct microbial invasion in every case."}, {"text": "Subdural empyema", "why": "Pus between dura and arachnoid can spread rapidly and cause fever, seizures, and focal deficits; contiguous sinus/ear disease is a possible source."}, {"text": "Meningitis", "why": "The dominant features reflect meningeal irritation. Altered consciousness can also occur in severe meningitis, so syndromes overlap rather than remaining absolutely separate."}], "answer": 4, "image": null}, {"id": "Q046", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 19], "page": 16, "ref": "slide-inf-16", "stem": "A febrile patient has persistent personality change, new seizures, and a focal neurologic deficit. MRI shows inflamed brain parenchyma. Which syndrome is present?", "options": [{"text": "Subdural empyema", "why": "Pus between dura and arachnoid can spread rapidly and cause fever, seizures, and focal deficits; contiguous sinus/ear disease is a possible source."}, {"text": "Encephalitis", "why": "Parenchymal dysfunction is central to encephalitis. Sustained altered mental status plus supportive findings distinguishes it from headache/neck stiffness alone."}, {"text": "Meningoencephalitis", "why": "Combined meningeal and parenchymal involvement can produce both neck stiffness/headache and sustained altered behavior, seizures, or focal deficits."}, {"text": "Meningitis", "why": "Meningeal inflammation commonly produces fever, headache, photophobia, and neck stiffness; predominant prolonged behavioral change or seizures suggests parenchymal involvement too."}, {"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}], "answer": 1, "image": null}, {"id": "Q047", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 19], "page": 16, "ref": "slide-inf-16", "stem": "Fever and nuchal rigidity occur together with prolonged confusion, seizures, and parenchymal MRI abnormalities. Which term best captures both sites?", "options": [{"text": "Meningoencephalitis", "why": "Meningeal and brain involvement produce overlapping symptoms. The term does not specify a single organism or exclude noninfectious inflammation."}, {"text": "Meningitis", "why": "Meningeal inflammation commonly produces fever, headache, photophobia, and neck stiffness; predominant prolonged behavioral change or seizures suggests parenchymal involvement too."}, {"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}, {"text": "Encephalitis", "why": "Brain parenchymal inflammation causes altered mental status, seizures, focal findings, and supportive CSF/MRI/EEG evidence rather than only meningeal irritation."}, {"text": "Acute flaccid myelitis", "why": "Acute anterior horn/spinal gray-matter injury can produce flaccid weakness and reduced reflexes, often with relatively spared sensation; not all cases are poliovirus."}], "answer": 0, "image": null}, {"id": "Q048", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 17, 19], "page": 16, "ref": "slide-inf-16", "stem": "Two weeks after a viral illness, a child develops encephalopathy and multifocal deficits with large white-matter lesions. Current fever is mild and infectious testing is unrevealing. Which syndrome fits?", "options": [{"text": "Subdural empyema", "why": "Pus between dura and arachnoid can spread rapidly and cause fever, seizures, and focal deficits; contiguous sinus/ear disease is a possible source."}, {"text": "Acute flaccid myelitis", "why": "Acute anterior horn/spinal gray-matter injury can produce flaccid weakness and reduced reflexes, often with relatively spared sensation; not all cases are poliovirus."}, {"text": "Meningitis", "why": "Meningeal inflammation commonly produces fever, headache, photophobia, and neck stiffness; predominant prolonged behavioral change or seizures suggests parenchymal involvement too."}, {"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}, {"text": "Acute disseminated encephalomyelitis", "why": "Postinfectious immune-mediated demyelination supports ADEM. It is an important example of postinfectious disease, but not a synonym for every postinfectious encephalopathy."}], "answer": 4, "image": null}, {"id": "Q049", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 17, 26], "page": 16, "ref": "slide-inf-16", "stem": "After a respiratory illness, a child develops acute asymmetric flaccid limb weakness and reduced reflexes. MRI predominantly affects spinal anterior horn gray matter. Poliovirus testing is negative. Which syndrome fits?", "options": [{"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}, {"text": "Acute flaccid myelitis", "why": "AFM is a clinical/radiologic syndrome with motor gray-matter injury and nonpolio causes, including some enteroviruses. Sensory findings are often less prominent than weakness."}, {"text": "Acute disseminated encephalomyelitis", "why": "ADEM is an immune-mediated multifocal demyelinating syndrome often after infection, with encephalopathy and predominantly white-matter lesions; it is not direct microbial invasion in every case."}, {"text": "Epidural abscess", "why": "An intracranial epidural collection lies between skull and dura; this is anatomically distinct from subdural pus or an intraparenchymal abscess."}, {"text": "Subdural empyema", "why": "Pus between dura and arachnoid can spread rapidly and cause fever, seizures, and focal deficits; contiguous sinus/ear disease is a possible source."}], "answer": 1, "image": null}, {"id": "Q050", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 26], "page": 16, "ref": "slide-inf-16", "stem": "A patient develops bilateral leg weakness, a truncal sensory level, and urinary retention. Cord inflammation spans the affected level. Which syndrome fits?", "options": [{"text": "Acute flaccid myelitis", "why": "Acute anterior horn/spinal gray-matter injury can produce flaccid weakness and reduced reflexes, often with relatively spared sensation; not all cases are poliovirus."}, {"text": "Meningitis", "why": "Meningeal inflammation commonly produces fever, headache, photophobia, and neck stiffness; predominant prolonged behavioral change or seizures suggests parenchymal involvement too."}, {"text": "Acute transverse myelitis", "why": "Motor, sensory, and autonomic involvement supports transverse myelitis. Symmetry is common but not absolute, and early reflexes may be reduced during spinal shock."}, {"text": "Encephalitis", "why": "Brain parenchymal inflammation causes altered mental status, seizures, focal findings, and supportive CSF/MRI/EEG evidence rather than only meningeal irritation."}, {"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}], "answer": 2, "image": null}, {"id": "Q051", "deck": "inf", "topic": "CNS syndrome localization", "pages": [18, 35], "page": 18, "ref": "slide-inf-18", "stem": "A patient with chronic sinus infection develops headache, a seizure, and focal weakness. MRI shows a parenchymal ring-enhancing collection with restricted diffusion. Which diagnosis fits?", "options": [{"text": "Brain abscess", "why": "Contiguous spread can produce a focal pyogenic collection with surrounding edema. Ring enhancement has a broad differential and must be interpreted with clinical and imaging details."}, {"text": "Epidural abscess", "why": "An intracranial epidural collection lies between skull and dura; this is anatomically distinct from subdural pus or an intraparenchymal abscess."}, {"text": "Encephalitis", "why": "Brain parenchymal inflammation causes altered mental status, seizures, focal findings, and supportive CSF/MRI/EEG evidence rather than only meningeal irritation."}, {"text": "Acute flaccid myelitis", "why": "Acute anterior horn/spinal gray-matter injury can produce flaccid weakness and reduced reflexes, often with relatively spared sensation; not all cases are poliovirus."}, {"text": "Acute transverse myelitis", "why": "Cord inflammation produces bilateral motor and sensory deficits with a sensory level and autonomic dysfunction; symmetry can vary and early spinal shock can be flaccid."}], "answer": 0, "image": null}, {"id": "Q052", "deck": "inf", "topic": "CNS syndrome localization", "pages": [18, 36], "page": 18, "ref": "slide-inf-18", "stem": "After bacterial sinusitis, a patient has fever, seizures, and a crescentic purulent collection between dura and arachnoid. Which diagnosis fits?", "options": [{"text": "Acute transverse myelitis", "why": "Cord inflammation produces bilateral motor and sensory deficits with a sensory level and autonomic dysfunction; symmetry can vary and early spinal shock can be flaccid."}, {"text": "Acute disseminated encephalomyelitis", "why": "ADEM is an immune-mediated multifocal demyelinating syndrome often after infection, with encephalopathy and predominantly white-matter lesions; it is not direct microbial invasion in every case."}, {"text": "Subdural empyema", "why": "The collection is subdural, not within brain tissue or outside dura. This is a neurosurgical/infectious emergency because rapid spread and mass effect can occur."}, {"text": "Epidural abscess", "why": "An intracranial epidural collection lies between skull and dura; this is anatomically distinct from subdural pus or an intraparenchymal abscess."}, {"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}], "answer": 2, "image": null}, {"id": "Q053", "deck": "inf", "topic": "CNS syndrome localization", "pages": [36], "page": 36, "ref": "slide-inf-36", "stem": "A focal infected collection lies between the inner skull surface and dura after skull osteomyelitis. Which term is anatomically correct?", "options": [{"text": "Acute disseminated encephalomyelitis", "why": "ADEM is an immune-mediated multifocal demyelinating syndrome often after infection, with encephalopathy and predominantly white-matter lesions; it is not direct microbial invasion in every case."}, {"text": "Encephalitis", "why": "Brain parenchymal inflammation causes altered mental status, seizures, focal findings, and supportive CSF/MRI/EEG evidence rather than only meningeal irritation."}, {"text": "Epidural abscess", "why": "Intracranial epidural infection occupies the extradural space. It is distinct from a spinal epidural abscess, although both are outside dura."}, {"text": "Meningoencephalitis", "why": "Combined meningeal and parenchymal involvement can produce both neck stiffness/headache and sustained altered behavior, seizures, or focal deficits."}, {"text": "Subdural empyema", "why": "Pus between dura and arachnoid can spread rapidly and cause fever, seizures, and focal deficits; contiguous sinus/ear disease is a possible source."}], "answer": 2, "image": null}, {"id": "Q054", "deck": "inf", "topic": "CNS syndrome localization", "pages": [16, 19], "page": 16, "ref": "slide-inf-16", "stem": "Which syndrome most specifically reflects immune attack on CNS myelin days to weeks after an infection rather than ongoing pathogen replication?", "options": [{"text": "Acute transverse myelitis", "why": "Cord inflammation produces bilateral motor and sensory deficits with a sensory level and autonomic dysfunction; symmetry can vary and early spinal shock can be flaccid."}, {"text": "Meningoencephalitis", "why": "Combined meningeal and parenchymal involvement can produce both neck stiffness/headache and sustained altered behavior, seizures, or focal deficits."}, {"text": "Brain abscess", "why": "Focal parenchymal infection can form a pus-containing lesion with edema and mass effect, often causing headache, seizures, or focal deficits."}, {"text": "Meningitis", "why": "Meningeal inflammation commonly produces fever, headache, photophobia, and neck stiffness; predominant prolonged behavioral change or seizures suggests parenchymal involvement too."}, {"text": "Acute disseminated encephalomyelitis", "why": "ADEM involves autoimmune inflammatory demyelination and often encephalopathy. Direct infection and autoimmune mechanisms require different diagnostic considerations."}], "answer": 4, "image": null}, {"id": "Q055", "deck": "inf", "topic": "CSF pattern recognition", "pages": [21, 30, 34], "page": 21, "ref": "slide-inf-21", "stem": "CSF has 3,200 WBC/µL with 90% neutrophils, protein 240 mg/dL, and glucose 25 mg/dL while serum glucose is 100 mg/dL. Which pattern is most likely?", "options": [{"text": "Acute pyogenic bacterial pattern", "why": "The marked neutrophilia, high protein, and ratio 0.25 support bacterial meningitis. Culture, Gram stain, and appropriate molecular testing are needed, and treatment should be prompt."}, {"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}, {"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Chronic lymphocytic inflammation, high protein, and often low glucose can occur; advanced immunosuppression may produce surprisingly few cells."}, {"text": "Tuberculous meningitis pattern", "why": "A subacute/chronic illness with lymphocytes, high protein, and low glucose suggests TB; smear is insensitive and culture/NAAT improve detection."}], "answer": 0, "image": null}, {"id": "Q056", "deck": "inf", "topic": "CSF pattern recognition", "pages": [20, 21, 30, 34], "page": 20, "ref": "slide-inf-20", "stem": "CSF has 140 WBC/µL, predominantly lymphocytes, protein 70 mg/dL, and preserved CSF:serum glucose ratio. Which common pattern fits an acute self-limited aseptic syndrome?", "options": [{"text": "Tuberculous meningitis pattern", "why": "A subacute/chronic illness with lymphocytes, high protein, and low glucose suggests TB; smear is insensitive and culture/NAAT improve detection."}, {"text": "Typical viral pattern", "why": "Typical viral CSF shows lymphocytic pleocytosis and normal glucose with modest protein elevation. This is a pattern, not definitive organism identification."}, {"text": "Acute pyogenic bacterial pattern", "why": "Neutrophilic pleocytosis, markedly increased protein, and low CSF:serum glucose ratio favor bacterial meningitis, but exceptions and pretreatment effects occur."}, {"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}, {"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}], "answer": 1, "image": null}, {"id": "Q057", "deck": "inf", "topic": "CSF pattern recognition", "pages": [18, 32, 34], "page": 18, "ref": "slide-inf-18", "stem": "A subacute headache illness has CSF with 220 lymphocyte-predominant WBC/µL, protein 280 mg/dL, and low glucose. TB exposure and basal meningeal abnormalities are present. Which pattern fits?", "options": [{"text": "Tuberculous meningitis pattern", "why": "Chronicity, lymphocytes, high protein, and low glucose with a compatible exposure favor TB. Fungal disease can resemble this, so specific tests are required."}, {"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Chronic lymphocytic inflammation, high protein, and often low glucose can occur; advanced immunosuppression may produce surprisingly few cells."}, {"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}, {"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}], "answer": 0, "image": null}, {"id": "Q058", "deck": "inf", "topic": "CSF pattern recognition", "pages": [18, 32, 34], "page": 18, "ref": "slide-inf-18", "stem": "A patient with syphilis has neurologic symptoms, 45 lymphocytes/µL, modest protein elevation, and normal glucose. Which pattern is compatible?", "options": [{"text": "Neurosyphilitic pattern", "why": "Neurosyphilis can cause a milder lymphocytic CSF profile. CSF VDRL and sensitive treponemal tests have different diagnostic roles."}, {"text": "Tuberculous meningitis pattern", "why": "A subacute/chronic illness with lymphocytes, high protein, and low glucose suggests TB; smear is insensitive and culture/NAAT improve detection."}, {"text": "Acute pyogenic bacterial pattern", "why": "Neutrophilic pleocytosis, markedly increased protein, and low CSF:serum glucose ratio favor bacterial meningitis, but exceptions and pretreatment effects occur."}, {"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}, {"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}], "answer": 0, "image": null}, {"id": "Q059", "deck": "inf", "topic": "CSF pattern recognition", "pages": [18, 32, 33, 34], "page": 18, "ref": "slide-inf-18", "stem": "Advanced HIV is associated with subacute headache, high opening pressure, and positive CSF cryptococcal antigen despite only 12 WBC/µL. Which pattern fits?", "options": [{"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}, {"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}, {"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}, {"text": "Acute pyogenic bacterial pattern", "why": "Neutrophilic pleocytosis, markedly increased protein, and low CSF:serum glucose ratio favor bacterial meningitis, but exceptions and pretreatment effects occur."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Profound immune suppression can blunt CSF inflammation in cryptococcosis. A low cell count does not exclude serious fungal CNS infection."}], "answer": 4, "image": null}, {"id": "Q060", "deck": "inf", "topic": "CSF pattern recognition", "pages": [34], "page": 34, "ref": "slide-inf-34", "stem": "After a relevant travel/food exposure, a patient has meningitis with a substantial CSF eosinophil fraction. Which broad pattern deserves consideration?", "options": [{"text": "Helminth-associated eosinophilic pattern", "why": "Eosinophilia suggests selected helminthic causes, not every parasite. Naegleria may cause a neutrophilic pattern and toxoplasmosis is often primarily parenchymal."}, {"text": "Tuberculous meningitis pattern", "why": "A subacute/chronic illness with lymphocytes, high protein, and low glucose suggests TB; smear is insensitive and culture/NAAT improve detection."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Chronic lymphocytic inflammation, high protein, and often low glucose can occur; advanced immunosuppression may produce surprisingly few cells."}, {"text": "Acute pyogenic bacterial pattern", "why": "Neutrophilic pleocytosis, markedly increased protein, and low CSF:serum glucose ratio favor bacterial meningitis, but exceptions and pretreatment effects occur."}, {"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}], "answer": 0, "image": null}, {"id": "Q061", "deck": "inf", "topic": "CSF pattern recognition", "pages": [21, 30], "page": 21, "ref": "slide-inf-21", "stem": "Which broad pattern usually has a CSF:serum glucose ratio below 0.4 in the deck's acute bacterial-versus-viral comparison?", "options": [{"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}, {"text": "Acute pyogenic bacterial pattern", "why": "Low CSF glucose relative to serum supports bacterial infection in this comparison. TB and fungal disease can also lower glucose, and a normal value does not exclude early bacterial disease."}, {"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Chronic lymphocytic inflammation, high protein, and often low glucose can occur; advanced immunosuppression may produce surprisingly few cells."}, {"text": "Tuberculous meningitis pattern", "why": "A subacute/chronic illness with lymphocytes, high protein, and low glucose suggests TB; smear is insensitive and culture/NAAT improve detection."}], "answer": 1, "image": null}, {"id": "Q062", "deck": "inf", "topic": "CSF pattern recognition", "pages": [21, 30], "page": 21, "ref": "slide-inf-21", "stem": "Which pattern most often preserves glucose despite an elevated lymphocyte count in an acute uncomplicated aseptic illness?", "options": [{"text": "Typical viral pattern", "why": "Preserved glucose is characteristic of many viral cases. CMV, mumps, and other exceptions mean glucose cannot classify all cases with certainty."}, {"text": "Acute pyogenic bacterial pattern", "why": "Neutrophilic pleocytosis, markedly increased protein, and low CSF:serum glucose ratio favor bacterial meningitis, but exceptions and pretreatment effects occur."}, {"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Chronic lymphocytic inflammation, high protein, and often low glucose can occur; advanced immunosuppression may produce surprisingly few cells."}, {"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}], "answer": 0, "image": null}, {"id": "Q063", "deck": "inf", "topic": "Diagnostic test selection", "pages": [21, 30], "page": 21, "ref": "slide-inf-21", "stem": "Which initial CSF studies can visualize common bacterial organisms and grow an isolate for susceptibility testing?", "options": [{"text": "CSF VDRL", "why": "A positive result in an appropriate non-bloody specimen is highly specific for neurosyphilis, but low sensitivity means a negative result does not exclude it."}, {"text": "CSF treponemal testing such as FTA-ABS or TPPA", "why": "These tests are more sensitive but less specific in this setting; a positive result must be interpreted with serum tests, symptoms, and other CSF evidence."}, {"text": "CSF mycobacterial NAAT and culture", "why": "TB-specific testing improves diagnosis compared with a single insensitive AFB smear, but negative results do not always exclude TB meningitis."}, {"text": "CSF Gram stain and bacterial culture", "why": "Gram stain can be rapid and culture supports organism identification and susceptibility. Negative results, especially after antibiotics, do not rule out bacterial infection."}, {"text": "CSF cryptococcal antigen", "why": "CrAg is a sensitive organism-directed test for cryptococcal CNS disease and is preferred to relying solely on India ink."}], "answer": 3, "image": null}, {"id": "Q064", "deck": "inf", "topic": "Diagnostic test selection", "pages": [20, 21, 25, 30], "page": 20, "ref": "slide-inf-20", "stem": "Which test is particularly useful for identifying HSV or enterovirus nucleic acid in CSF?", "options": [{"text": "CSF treponemal testing such as FTA-ABS or TPPA", "why": "These tests are more sensitive but less specific in this setting; a positive result must be interpreted with serum tests, symptoms, and other CSF evidence."}, {"text": "CSF differential with exposure-directed serology/PCR", "why": "Counting eosinophils and choosing parasite-specific testing can evaluate suspected eosinophilic meningitis; no single broad test covers all parasites."}, {"text": "CSF mycobacterial NAAT and culture", "why": "TB-specific testing improves diagnosis compared with a single insensitive AFB smear, but negative results do not always exclude TB meningitis."}, {"text": "CSF pathogen-specific PCR or validated multiplex PCR", "why": "CSF PCR can establish a viral diagnosis in the right syndrome. A negative early HSV result may require repeat testing if suspicion remains high."}, {"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}], "answer": 3, "image": null}, {"id": "Q065", "deck": "inf", "topic": "Diagnostic test selection", "pages": [32, 34], "page": 32, "ref": "slide-inf-32", "stem": "Which CSF assay is preferred when cryptococcal meningitis is suspected?", "options": [{"text": "CSF differential with exposure-directed serology/PCR", "why": "Counting eosinophils and choosing parasite-specific testing can evaluate suspected eosinophilic meningitis; no single broad test covers all parasites."}, {"text": "CSF VDRL", "why": "A positive result in an appropriate non-bloody specimen is highly specific for neurosyphilis, but low sensitivity means a negative result does not exclude it."}, {"text": "CSF wet mount with ameba-directed testing", "why": "Fresh-sample microscopy can reveal motile amebas in PAM, with specific PCR/reference testing used for confirmation."}, {"text": "CSF cryptococcal antigen", "why": "CrAg detects cryptococcal capsular antigen and is more sensitive than relying only on India ink. It is not a universal test for every fungus."}, {"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}], "answer": 3, "image": null}, {"id": "Q066", "deck": "inf", "topic": "Diagnostic test selection", "pages": [32, 34], "page": 32, "ref": "slide-inf-32", "stem": "A single AFB smear is negative in suspected TB meningitis. Which tests should still be pursued?", "options": [{"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}, {"text": "CSF cryptococcal antigen", "why": "CrAg is a sensitive organism-directed test for cryptococcal CNS disease and is preferred to relying solely on India ink."}, {"text": "CSF differential with exposure-directed serology/PCR", "why": "Counting eosinophils and choosing parasite-specific testing can evaluate suspected eosinophilic meningitis; no single broad test covers all parasites."}, {"text": "CSF mycobacterial NAAT and culture", "why": "A smear has limited sensitivity. TB-specific molecular tests and culture are important, but clinical suspicion still matters after negative results."}, {"text": "CSF wet mount with ameba-directed testing", "why": "Fresh-sample microscopy can reveal motile amebas in PAM, with specific PCR/reference testing used for confirmation."}], "answer": 3, "image": null}, {"id": "Q067", "deck": "inf", "topic": "Diagnostic test selection", "pages": [32, 34], "page": 32, "ref": "slide-inf-32", "stem": "Which CSF syphilis test is relatively specific but insufficiently sensitive to exclude disease when negative?", "options": [{"text": "CSF mycobacterial NAAT and culture", "why": "TB-specific testing improves diagnosis compared with a single insensitive AFB smear, but negative results do not always exclude TB meningitis."}, {"text": "CSF VDRL", "why": "A positive CSF VDRL supports neurosyphilis in context, but a negative result cannot independently exclude it."}, {"text": "EEG", "why": "EEG can support encephalitis or detect seizures/nonconvulsive status; it does not by itself identify the infectious agent."}, {"text": "CSF treponemal testing such as FTA-ABS or TPPA", "why": "These tests are more sensitive but less specific in this setting; a positive result must be interpreted with serum tests, symptoms, and other CSF evidence."}, {"text": "CSF cryptococcal antigen", "why": "CrAg is a sensitive organism-directed test for cryptococcal CNS disease and is preferred to relying solely on India ink."}], "answer": 1, "image": null}, {"id": "Q068", "deck": "inf", "topic": "Diagnostic test selection", "pages": [32, 34], "page": 32, "ref": "slide-inf-32", "stem": "Which CSF tests are more sensitive than VDRL for neurosyphilis but require caution about specificity?", "options": [{"text": "CSF Gram stain and bacterial culture", "why": "These can identify pyogenic organisms and permit susceptibility assessment, but pretreatment or low organism burden reduces sensitivity."}, {"text": "CSF wet mount with ameba-directed testing", "why": "Fresh-sample microscopy can reveal motile amebas in PAM, with specific PCR/reference testing used for confirmation."}, {"text": "CSF treponemal testing such as FTA-ABS or TPPA", "why": "Treponemal tests can support evaluation, especially after a negative VDRL, but serum antibody diffusion and clinical context affect interpretation."}, {"text": "EEG", "why": "EEG can support encephalitis or detect seizures/nonconvulsive status; it does not by itself identify the infectious agent."}, {"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}], "answer": 2, "image": null}, {"id": "Q069", "deck": "inf", "topic": "Diagnostic test selection", "pages": [18, 34], "page": 18, "ref": "slide-inf-18", "stem": "A rapidly progressive meningitis after warm freshwater nasal exposure has motile organisms in fresh CSF. Which diagnostic approach is relevant?", "options": [{"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}, {"text": "CSF treponemal testing such as FTA-ABS or TPPA", "why": "These tests are more sensitive but less specific in this setting; a positive result must be interpreted with serum tests, symptoms, and other CSF evidence."}, {"text": "CSF differential with exposure-directed serology/PCR", "why": "Counting eosinophils and choosing parasite-specific testing can evaluate suspected eosinophilic meningitis; no single broad test covers all parasites."}, {"text": "CSF cryptococcal antigen", "why": "CrAg is a sensitive organism-directed test for cryptococcal CNS disease and is preferred to relying solely on India ink."}, {"text": "CSF wet mount with ameba-directed testing", "why": "Naegleria trophozoites may be visible in a fresh wet mount. Specific reference PCR/microscopy confirms identity rather than treating the organisms as leukocytes."}], "answer": 4, "image": null}, {"id": "Q070", "deck": "inf", "topic": "Diagnostic test selection", "pages": [34], "page": 34, "ref": "slide-inf-34", "stem": "Meningitis with CSF eosinophilia follows a compatible parasitic exposure. Which diagnostic approach is appropriate?", "options": [{"text": "CSF VDRL", "why": "A positive result in an appropriate non-bloody specimen is highly specific for neurosyphilis, but low sensitivity means a negative result does not exclude it."}, {"text": "CSF mycobacterial NAAT and culture", "why": "TB-specific testing improves diagnosis compared with a single insensitive AFB smear, but negative results do not always exclude TB meningitis."}, {"text": "CSF differential with exposure-directed serology/PCR", "why": "The differential highlights eosinophils; serologic or molecular testing is selected for the suspected parasite and local availability."}, {"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}, {"text": "CSF cryptococcal antigen", "why": "CrAg is a sensitive organism-directed test for cryptococcal CNS disease and is preferred to relying solely on India ink."}], "answer": 2, "image": null}, {"id": "Q071", "deck": "inf", "topic": "Diagnostic test selection", "pages": [19, 25], "page": 19, "ref": "slide-inf-19", "stem": "A confused patient has episodes of unresponsiveness and suspected nonconvulsive seizures during encephalitis. Which test directly evaluates electrical seizure activity?", "options": [{"text": "EEG", "why": "EEG can identify seizure activity and support parenchymal dysfunction. It complements MRI and CSF rather than identifying a virus by itself."}, {"text": "CSF cryptococcal antigen", "why": "CrAg is a sensitive organism-directed test for cryptococcal CNS disease and is preferred to relying solely on India ink."}, {"text": "Contrast-enhanced brain MRI", "why": "Imaging localizes parenchymal inflammation, abscesses, mass effect, and extra-axial collections rather than directly replacing microbiologic testing."}, {"text": "CSF mycobacterial NAAT and culture", "why": "TB-specific testing improves diagnosis compared with a single insensitive AFB smear, but negative results do not always exclude TB meningitis."}, {"text": "CSF pathogen-specific PCR or validated multiplex PCR", "why": "Molecular testing detects pathogen nucleic acid and is useful for enteroviruses, HSV, and selected bacteria; panel coverage and timing limit interpretation."}], "answer": 0, "image": null}, {"id": "Q072", "deck": "inf", "topic": "Diagnostic test selection", "pages": [25, 35, 36], "page": 25, "ref": "slide-inf-25", "stem": "A focal neurologic deficit raises concern for abscess, empyema, or encephalitic injury. Which study best localizes the structural lesion?", "options": [{"text": "CSF differential with exposure-directed serology/PCR", "why": "Counting eosinophils and choosing parasite-specific testing can evaluate suspected eosinophilic meningitis; no single broad test covers all parasites."}, {"text": "Contrast-enhanced brain MRI", "why": "MRI helps define parenchymal versus extra-axial disease, edema, and mass effect. Imaging may need to precede LP when a mass lesion or other contraindication is suspected."}, {"text": "CSF VDRL", "why": "A positive result in an appropriate non-bloody specimen is highly specific for neurosyphilis, but low sensitivity means a negative result does not exclude it."}, {"text": "CSF treponemal testing such as FTA-ABS or TPPA", "why": "These tests are more sensitive but less specific in this setting; a positive result must be interpreted with serum tests, symptoms, and other CSF evidence."}, {"text": "EEG", "why": "EEG can support encephalitis or detect seizures/nonconvulsive status; it does not by itself identify the infectious agent."}], "answer": 1, "image": null}, {"id": "Q073", "deck": "inf", "topic": "CSF calculation", "pages": [21, 30], "page": 21, "ref": "slide-inf-21", "stem": "CSF glucose is 36 mg/dL and serum glucose is 120 mg/dL. What is the CSF:serum ratio?", "options": [{"text": "0.03", "why": "This is a tenfold calculation error."}, {"text": "0.30", "why": "Divide 36 by 120. This low ratio supports a bacterial, TB, fungal, or other hypoglycorrhachic process in context rather than a typical uncomplicated viral pattern."}, {"text": "0.60", "why": "That would require CSF glucose of 72 mg/dL with this serum value."}, {"text": "3.33", "why": "That reverses the numerator and denominator."}, {"text": "1.20", "why": "This does not equal 36 divided by 120."}], "answer": 1, "image": null}, {"id": "Q074", "deck": "inf", "topic": "CSF interpretation limits", "pages": [21, 30], "page": 21, "ref": "slide-inf-21", "stem": "Early CSF in a PCR-confirmed enteroviral illness is neutrophil predominant. Which interpretation is appropriate?", "options": [{"text": "PCR never adds useful diagnostic information", "why": "Validated PCR is useful when interpreted with timing and clinical context."}, {"text": "A low protein value alone proves a bacterial cause", "why": "Protein is not independently definitive."}, {"text": "A normal glucose value excludes all bacterial disease", "why": "Early or partially treated disease can be atypical."}, {"text": "Early viral meningitis can be neutrophilic", "why": "Cell type is probabilistic. Early neutrophils do not exclude viral disease, but possible bacterial meningitis still requires urgent assessment rather than automatic reassurance."}, {"text": "Neutrophils make any viral diagnosis impossible", "why": "The deck explicitly notes early viral PMNs."}], "answer": 3, "image": null}, {"id": "Q075", "deck": "inf", "topic": "CSF interpretation limits", "pages": [21, 30], "page": 21, "ref": "slide-inf-21", "stem": "Which bacterial pathogen can produce a mixed or mononuclear CSF response rather than the classic neutrophil pattern?", "options": [{"text": "Adenovirus", "why": "This is a virus, not the asked bacterial exception."}, {"text": "Cryptococcus neoformans", "why": "This is a fungus."}, {"text": "Coxsackievirus", "why": "This is an enterovirus rather than a bacterium."}, {"text": "Listeria monocytogenes", "why": "Listerial meningitis can have mixed or mononuclear cells, so host risk and microbiology matter more than a rigid bacterial/viral cell-type rule."}, {"text": "Toxoplasma gondii", "why": "This is a protozoan rather than a bacterium."}], "answer": 3, "image": null}, {"id": "Q076", "deck": "inf", "topic": "Encephalitis criteria", "pages": [19], "page": 19, "ref": "slide-inf-19", "stem": "Which major feature is required by the International Encephalitis Consortium clinical case definition?", "options": [{"text": "Headache alone for one hour", "why": "Headache is nonspecific and does not satisfy the major altered-mental-status criterion."}, {"text": "Neck stiffness without any brain dysfunction", "why": "That can support meningitis but is not the encephalitis major criterion."}, {"text": "Altered mental status lasting at least 24 hours with no better alternative cause", "why": "The definition then uses supportive minor findings such as fever, seizures, focal signs, pleocytosis, MRI, or EEG. It is a classification framework, not a reason to defer urgent treatment."}, {"text": "Only a positive serum IgG to a remote infection", "why": "Past exposure does not establish current brain inflammation."}, {"text": "Only a normal EEG", "why": "A normal EEG does not establish encephalitis."}], "answer": 2, "image": null}, {"id": "Q077", "deck": "inf", "topic": "Encephalitis criteria", "pages": [19], "page": 19, "ref": "slide-inf-19", "stem": "Altered mental status has persisted for two days without another cause, and fever, new seizures, and compatible MRI changes are present. Which classification is supported?", "options": [{"text": "Only uncomplicated conjunctivitis", "why": "Sustained brain dysfunction and seizures are not explained by superficial eye inflammation."}, {"text": "Confirmed infection by a specific virus without any organism evidence", "why": "The syndrome criteria do not themselves identify or confirm a particular pathogen."}, {"text": "A mandatory diagnosis of bacterial meningitis", "why": "The criteria define a parenchymal syndrome, not one microbial category."}, {"text": "Probable encephalitis by the major plus at least three minor criteria", "why": "Two minor findings support possible encephalitis and at least three support probable classification. Confirmed disease additionally requires appropriate etiologic/pathologic evidence."}, {"text": "No encephalitis because headache is absent", "why": "Headache is not required and is not one of the formal six minor criteria."}], "answer": 3, "image": null}, {"id": "Q078", "deck": "inf", "topic": "Meningeal signs", "pages": [31], "page": 31, "ref": "slide-inf-31", "stem": "Neck flexion produces involuntary flexion at the hips and knees. Which sign is this?", "options": [{"text": "Dix-Hallpike response", "why": "That evaluates positional vestibular nystagmus, not meningismus."}, {"text": "Kernig sign", "why": "Kernig refers to pain/resistance with knee extension when the hip is flexed."}, {"text": "Brudzinski sign", "why": "Meningeal irritation can cause reflex hip/knee flexion with passive neck flexion. Sensitivity is limited, so absence does not exclude meningitis."}, {"text": "Babinski sign", "why": "An extensor plantar response is an upper motor neuron sign, not this neck maneuver."}, {"text": "Romberg sign", "why": "This evaluates postural stability with visual input removed."}], "answer": 2, "image": null}, {"id": "Q079", "deck": "inf", "topic": "Meningeal signs", "pages": [31], "page": 31, "ref": "slide-inf-31", "stem": "A patient has pain and resistance when extending the knee while the hip is flexed. Which sign is present?", "options": [{"text": "A relative afferent pupillary defect", "why": "This is an optic afferent examination finding."}, {"text": "Horner syndrome", "why": "Ptosis, miosis, and anhidrosis reflect sympathetic dysfunction."}, {"text": "A positive Rinne test", "why": "That compares air and bone hearing."}, {"text": "Brudzinski sign", "why": "That is hip/knee flexion provoked by neck flexion."}, {"text": "Kernig sign", "why": "Stretching irritated meninges can cause this response. A negative sign does not safely rule out meningitis."}], "answer": 4, "image": null}, {"id": "Q080", "deck": "inf", "topic": "Age-dependent meningitis", "pages": [31], "page": 31, "ref": "slide-inf-31", "stem": "Which presentation is particularly important in an infant with bacterial meningitis?", "options": [{"text": "A requirement that the infant describe severe headache verbally", "why": "Preverbal children cannot reliably report the adult symptom pattern."}, {"text": "Only seasonal itchy eyes", "why": "That suggests a different superficial allergic process."}, {"text": "A fully reliable absence of disease when neck stiffness is absent", "why": "Classic meningeal signs can be absent in infants."}, {"text": "Poor feeding, irritability, lethargy, apnea, or a bulging fontanel", "why": "Infants may lack the classic adult description of headache and stiff neck. Seizures, altered consciousness, and purpura can also occur."}, {"text": "Only a gradual isolated conductive hearing loss over years", "why": "That does not capture an acute systemic CNS infection."}], "answer": 3, "image": null}, {"id": "Q081", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 31], "page": 18, "ref": "slide-inf-18", "stem": "A neonate develops fever, poor feeding, lethargy, and meningitis. Blood culture grows beta-hemolytic gram-positive cocci that are CAMP positive. Which organism fits?", "options": [{"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus is a major bacterial meningitis agent, associated with respiratory/ear sources and risk after CSF leaks or asplenia."}, {"text": "Group B Streptococcus", "why": "S. agalactiae is a major neonatal meningitis pathogen. The age and microbiology distinguish it from common older-child meningococci or pneumococci."}, {"text": "Mycobacterium tuberculosis", "why": "TB causes subacute/chronic meningitis, often with basal inflammation, high protein, low glucose, and lymphocytic cells."}, {"text": "Treponema pallidum", "why": "Syphilis can involve meninges or produce other neurologic/ocular syndromes; CSF VDRL is specific but not highly sensitive."}, {"text": "Streptococcal oral/sinus flora", "why": "Streptococci, often with anaerobic partners, can cause brain abscess through contiguous dental/sinus infection."}], "answer": 1, "image": null}, {"id": "Q082", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 31], "page": 18, "ref": "slide-inf-18", "stem": "A neonate has meningitis caused by a gram-negative enteric rod with a K1 capsule. Which organism fits?", "options": [{"text": "Group B Streptococcus", "why": "Streptococcus agalactiae is a major neonatal invasive pathogen acquired around birth; it is not the usual adolescent dormitory meningococcus."}, {"text": "Haemophilus influenzae type b", "why": "Encapsulated Hib can cause invasive meningitis, especially in underimmunized children; it is distinct from nontypeable AOM strains."}, {"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus is a major bacterial meningitis agent, associated with respiratory/ear sources and risk after CSF leaks or asplenia."}, {"text": "Escherichia coli", "why": "E. coli is an important neonatal CNS pathogen, and the K1 capsule is associated with neuroinvasive strains."}, {"text": "Borrelia burgdorferi", "why": "Lyme neuroborreliosis can cause lymphocytic meningitis, facial palsy, and painful radiculoneuritis after tick exposure."}], "answer": 3, "image": null}, {"id": "Q083", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 31, 37], "page": 18, "ref": "slide-inf-18", "stem": "A college student with fever, neck stiffness, and rapidly progressive purpura has gram-negative diplococci in CSF. Which pathogen is most likely?", "options": [{"text": "Listeria monocytogenes", "why": "This gram-positive intracellular rod causes meningitis in neonates, older adults, and immunocompromised patients, sometimes with mixed CSF cells."}, {"text": "Escherichia coli", "why": "E. coli, particularly strains with a K1 capsule, is an important gram-negative neonatal meningitis cause."}, {"text": "Neisseria meningitidis", "why": "Meningococcal meningitis can accompany invasive bacteremia and a nonblanching petechial/purpuric rash. This is an urgent illness; rash is neither required nor uniquely diagnostic."}, {"text": "Group B Streptococcus", "why": "Streptococcus agalactiae is a major neonatal invasive pathogen acquired around birth; it is not the usual adolescent dormitory meningococcus."}, {"text": "Streptococcal oral/sinus flora", "why": "Streptococci, often with anaerobic partners, can cause brain abscess through contiguous dental/sinus infection."}], "answer": 2, "image": null}, {"id": "Q084", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 37], "page": 18, "ref": "slide-inf-18", "stem": "An asplenic adult develops acute meningitis with encapsulated gram-positive diplococci. Which organism is most likely?", "options": [{"text": "Staphylococcus aureus", "why": "S. aureus is important in postoperative/traumatic CNS infection and hematogenous abscess, including with endocarditis."}, {"text": "Streptococcal oral/sinus flora", "why": "Streptococci, often with anaerobic partners, can cause brain abscess through contiguous dental/sinus infection."}, {"text": "Treponema pallidum", "why": "Syphilis can involve meninges or produce other neurologic/ocular syndromes; CSF VDRL is specific but not highly sensitive."}, {"text": "Streptococcus pneumoniae", "why": "Pneumococcal invasive disease is promoted by impaired clearance of encapsulated bacteria. Ear/sinus infection or a CSF leak can also be relevant sources/risks."}, {"text": "Mycobacterium tuberculosis", "why": "TB causes subacute/chronic meningitis, often with basal inflammation, high protein, low glucose, and lymphocytic cells."}], "answer": 3, "image": null}, {"id": "Q085", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 21, 37], "page": 18, "ref": "slide-inf-18", "stem": "An older patient on immunosuppressive therapy develops meningitis caused by a gram-positive rod with tumbling motility. Which organism fits?", "options": [{"text": "Listeria monocytogenes", "why": "Listeria is important in older/immunocompromised hosts and neonates. Its CSF differential can be mixed; routine cephalosporins do not provide reliable coverage."}, {"text": "Treponema pallidum", "why": "Syphilis can involve meninges or produce other neurologic/ocular syndromes; CSF VDRL is specific but not highly sensitive."}, {"text": "Neisseria meningitidis", "why": "An encapsulated gram-negative diplococcus can cause acute meningitis and bacteremia with petechiae/purpura, especially in crowded close-contact settings."}, {"text": "Escherichia coli", "why": "E. coli, particularly strains with a K1 capsule, is an important gram-negative neonatal meningitis cause."}, {"text": "Group B Streptococcus", "why": "Streptococcus agalactiae is a major neonatal invasive pathogen acquired around birth; it is not the usual adolescent dormitory meningococcus."}], "answer": 0, "image": null}, {"id": "Q086", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 37], "page": 18, "ref": "slide-inf-18", "stem": "An underimmunized young child develops meningitis caused by an encapsulated type b gram-negative coccobacillus. Which agent fits?", "options": [{"text": "Treponema pallidum", "why": "Syphilis can involve meninges or produce other neurologic/ocular syndromes; CSF VDRL is specific but not highly sensitive."}, {"text": "Haemophilus influenzae type b", "why": "Hib invasive disease differs from common nontypeable middle-ear disease. Vaccination changes population incidence but does not make every H. influenzae infection vaccine-preventable."}, {"text": "Listeria monocytogenes", "why": "This gram-positive intracellular rod causes meningitis in neonates, older adults, and immunocompromised patients, sometimes with mixed CSF cells."}, {"text": "Mycobacterium tuberculosis", "why": "TB causes subacute/chronic meningitis, often with basal inflammation, high protein, low glucose, and lymphocytic cells."}, {"text": "Escherichia coli", "why": "E. coli, particularly strains with a K1 capsule, is an important gram-negative neonatal meningitis cause."}], "answer": 1, "image": null}, {"id": "Q087", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 32, 34], "page": 18, "ref": "slide-inf-18", "stem": "Weeks of headache and low-grade fever are followed by cranial neuropathies and basal meningeal inflammation. CSF has lymphocytes, high protein, and low glucose. Which organism is a key concern?", "options": [{"text": "Mycobacterium tuberculosis", "why": "TB meningitis is a subacute/chronic process with characteristic basal complications. NAAT and culture are more useful than relying only on an insensitive smear."}, {"text": "Haemophilus influenzae type b", "why": "Encapsulated Hib can cause invasive meningitis, especially in underimmunized children; it is distinct from nontypeable AOM strains."}, {"text": "Borrelia burgdorferi", "why": "Lyme neuroborreliosis can cause lymphocytic meningitis, facial palsy, and painful radiculoneuritis after tick exposure."}, {"text": "Streptococcal oral/sinus flora", "why": "Streptococci, often with anaerobic partners, can cause brain abscess through contiguous dental/sinus infection."}, {"text": "Group B Streptococcus", "why": "Streptococcus agalactiae is a major neonatal invasive pathogen acquired around birth; it is not the usual adolescent dormitory meningococcus."}], "answer": 0, "image": null}, {"id": "Q088", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 32, 34], "page": 18, "ref": "slide-inf-18", "stem": "A patient has neurologic symptoms with reactive syphilis serology and a positive CSF VDRL. Which organism causes the underlying infection?", "options": [{"text": "Neisseria meningitidis", "why": "An encapsulated gram-negative diplococcus can cause acute meningitis and bacteremia with petechiae/purpura, especially in crowded close-contact settings."}, {"text": "Listeria monocytogenes", "why": "This gram-positive intracellular rod causes meningitis in neonates, older adults, and immunocompromised patients, sometimes with mixed CSF cells."}, {"text": "Group B Streptococcus", "why": "Streptococcus agalactiae is a major neonatal invasive pathogen acquired around birth; it is not the usual adolescent dormitory meningococcus."}, {"text": "Treponema pallidum", "why": "T. pallidum can cause meningitis and broader neurosyphilitic syndromes. A positive appropriately interpreted CSF VDRL supports CNS involvement."}, {"text": "Haemophilus influenzae type b", "why": "Encapsulated Hib can cause invasive meningitis, especially in underimmunized children; it is distinct from nontypeable AOM strains."}], "answer": 3, "image": null}, {"id": "Q089", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18], "page": 18, "ref": "slide-inf-18", "stem": "A patient develops facial palsy, radicular pain, and lymphocytic meningitis after a tick exposure and expanding annular rash. Which pathogen fits?", "options": [{"text": "Neisseria meningitidis", "why": "An encapsulated gram-negative diplococcus can cause acute meningitis and bacteremia with petechiae/purpura, especially in crowded close-contact settings."}, {"text": "Mycobacterium tuberculosis", "why": "TB causes subacute/chronic meningitis, often with basal inflammation, high protein, low glucose, and lymphocytic cells."}, {"text": "Haemophilus influenzae type b", "why": "Encapsulated Hib can cause invasive meningitis, especially in underimmunized children; it is distinct from nontypeable AOM strains."}, {"text": "Borrelia burgdorferi", "why": "This constellation supports Lyme neuroborreliosis. The organism can involve meninges, cranial nerves, and roots rather than causing only a nonspecific rash."}, {"text": "Escherichia coli", "why": "E. coli, particularly strains with a K1 capsule, is an important gram-negative neonatal meningitis cause."}], "answer": 3, "image": null}, {"id": "Q090", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 35], "page": 18, "ref": "slide-inf-18", "stem": "A patient with S. aureus endocarditis develops a focal brain abscess. Which organism is most directly implicated?", "options": [{"text": "Staphylococcus aureus", "why": "Hematogenous seeding from endocarditis can cause brain infection. This differs from the mixed oral/anaerobic flora often found after contiguous sinus or dental spread."}, {"text": "Listeria monocytogenes", "why": "This gram-positive intracellular rod causes meningitis in neonates, older adults, and immunocompromised patients, sometimes with mixed CSF cells."}, {"text": "Group B Streptococcus", "why": "Streptococcus agalactiae is a major neonatal invasive pathogen acquired around birth; it is not the usual adolescent dormitory meningococcus."}, {"text": "Streptococcal oral/sinus flora", "why": "Streptococci, often with anaerobic partners, can cause brain abscess through contiguous dental/sinus infection."}, {"text": "Haemophilus influenzae type b", "why": "Encapsulated Hib can cause invasive meningitis, especially in underimmunized children; it is distinct from nontypeable AOM strains."}], "answer": 0, "image": null}, {"id": "Q091", "deck": "inf", "topic": "Bacterial pathogen recognition", "pages": [18, 35, 36], "page": 18, "ref": "slide-inf-18", "stem": "A brain abscess develops adjacent to an infected sinus; culture grows streptococci and anaerobes. Which microbial group best fits the source?", "options": [{"text": "Streptococcal oral/sinus flora", "why": "Contiguous spread commonly involves streptococci and anaerobic partners. The source guides empiric coverage and diagnostic sampling."}, {"text": "Staphylococcus aureus", "why": "S. aureus is important in postoperative/traumatic CNS infection and hematogenous abscess, including with endocarditis."}, {"text": "Treponema pallidum", "why": "Syphilis can involve meninges or produce other neurologic/ocular syndromes; CSF VDRL is specific but not highly sensitive."}, {"text": "Listeria monocytogenes", "why": "This gram-positive intracellular rod causes meningitis in neonates, older adults, and immunocompromised patients, sometimes with mixed CSF cells."}, {"text": "Mycobacterium tuberculosis", "why": "TB causes subacute/chronic meningitis, often with basal inflammation, high protein, low glucose, and lymphocytic cells."}], "answer": 0, "image": null}, {"id": "Q092", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [20, 22], "page": 20, "ref": "slide-inf-20", "stem": "After mucosal replication, a virus enters the blood, amplifies in secondary sites, and crosses into the CNS. Which route is described?", "options": [{"text": "Retrograde axonal transport", "why": "Some neurotropic pathogens travel from peripheral nerves toward neuronal cell bodies/CNS, as in rabies and herpes pathways."}, {"text": "Direct traumatic or procedural inoculation", "why": "Penetrating injury or surgery can introduce organisms past normal protective barriers."}, {"text": "Postinfectious autoimmune injury", "why": "Immune-mediated inflammation/demyelination after infection differs from direct ongoing microorganism invasion."}, {"text": "Direct contiguous spread", "why": "Sinus, middle-ear, mastoid, skull, or dental infection can extend into nearby intracranial compartments."}, {"text": "Hematogenous dissemination", "why": "Viremia can precede barrier crossing. Some pathogens also use infected leukocytes; target-cell tropism influences the resulting syndrome."}], "answer": 4, "image": null}, {"id": "Q093", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [20, 22, 27], "page": 20, "ref": "slide-inf-20", "stem": "A virus enters peripheral neurons at a bite site and travels toward the spinal cord/brain. Which route is described?", "options": [{"text": "Postinfectious autoimmune injury", "why": "Immune-mediated inflammation/demyelination after infection differs from direct ongoing microorganism invasion."}, {"text": "Direct traumatic or procedural inoculation", "why": "Penetrating injury or surgery can introduce organisms past normal protective barriers."}, {"text": "Direct contiguous spread", "why": "Sinus, middle-ear, mastoid, skull, or dental infection can extend into nearby intracranial compartments."}, {"text": "Hematogenous dissemination", "why": "Viremia, bacteremia, or fungemia can deliver organisms to CNS interfaces, crossing barriers or trafficking with infected cells."}, {"text": "Retrograde axonal transport", "why": "Rabies uses neural transport after peripheral inoculation. This route differs from ordinary bloodstream dissemination."}], "answer": 4, "image": null}, {"id": "Q094", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [29], "page": 29, "ref": "slide-inf-29", "stem": "Nasopharyngeal bacterial colonization is followed by local invasion, bacteremia, and meningeal entry. Which dissemination route is central?", "options": [{"text": "Hematogenous dissemination", "why": "Transient bacteremia can precede meningeal invasion. Barrier disruption and the host inflammatory response produce CNS injury after entry."}, {"text": "Postinfectious autoimmune injury", "why": "Immune-mediated inflammation/demyelination after infection differs from direct ongoing microorganism invasion."}, {"text": "Direct traumatic or procedural inoculation", "why": "Penetrating injury or surgery can introduce organisms past normal protective barriers."}, {"text": "Retrograde axonal transport", "why": "Some neurotropic pathogens travel from peripheral nerves toward neuronal cell bodies/CNS, as in rabies and herpes pathways."}, {"text": "Direct contiguous spread", "why": "Sinus, middle-ear, mastoid, skull, or dental infection can extend into nearby intracranial compartments."}], "answer": 0, "image": null}, {"id": "Q095", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "Disseminated fungal infection seeds the meninges and brain from blood. Which route is described?", "options": [{"text": "Postinfectious autoimmune injury", "why": "Immune-mediated inflammation/demyelination after infection differs from direct ongoing microorganism invasion."}, {"text": "Retrograde axonal transport", "why": "Some neurotropic pathogens travel from peripheral nerves toward neuronal cell bodies/CNS, as in rabies and herpes pathways."}, {"text": "Direct contiguous spread", "why": "Sinus, middle-ear, mastoid, skull, or dental infection can extend into nearby intracranial compartments."}, {"text": "Hematogenous dissemination", "why": "The deck emphasizes bloodstream spread in fungal CNS disease. Host immune state and the organism determine meningeal, vascular, or parenchymal manifestations."}, {"text": "Direct traumatic or procedural inoculation", "why": "Penetrating injury or surgery can introduce organisms past normal protective barriers."}], "answer": 3, "image": null}, {"id": "Q096", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [35, 36], "page": 35, "ref": "slide-inf-35", "stem": "A sinus infection spreads into the adjacent subdural space. Which route is present?", "options": [{"text": "Direct traumatic or procedural inoculation", "why": "Penetrating injury or surgery can introduce organisms past normal protective barriers."}, {"text": "Direct contiguous spread", "why": "Nearby infected skull/air sinus structures can extend intracranially. This can lead to empyema or abscess without requiring a primary bloodstream source."}, {"text": "Postinfectious autoimmune injury", "why": "Immune-mediated inflammation/demyelination after infection differs from direct ongoing microorganism invasion."}, {"text": "Retrograde axonal transport", "why": "Some neurotropic pathogens travel from peripheral nerves toward neuronal cell bodies/CNS, as in rabies and herpes pathways."}, {"text": "Hematogenous dissemination", "why": "Viremia, bacteremia, or fungemia can deliver organisms to CNS interfaces, crossing barriers or trafficking with infected cells."}], "answer": 1, "image": null}, {"id": "Q097", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [35], "page": 35, "ref": "slide-inf-35", "stem": "A penetrating skull wound is followed by localized intracranial infection. Which route fits?", "options": [{"text": "Postinfectious autoimmune injury", "why": "Immune-mediated inflammation/demyelination after infection differs from direct ongoing microorganism invasion."}, {"text": "Direct traumatic or procedural inoculation", "why": "Barrier disruption permits direct entry from a wound or procedure. The inoculation context affects likely organisms."}, {"text": "Retrograde axonal transport", "why": "Some neurotropic pathogens travel from peripheral nerves toward neuronal cell bodies/CNS, as in rabies and herpes pathways."}, {"text": "Direct contiguous spread", "why": "Sinus, middle-ear, mastoid, skull, or dental infection can extend into nearby intracranial compartments."}, {"text": "Hematogenous dissemination", "why": "Viremia, bacteremia, or fungemia can deliver organisms to CNS interfaces, crossing barriers or trafficking with infected cells."}], "answer": 1, "image": null}, {"id": "Q098", "deck": "inf", "topic": "Routes and pathogenesis", "pages": [16, 17, 19], "page": 16, "ref": "slide-inf-16", "stem": "White-matter demyelination begins after an infection has clinically resolved, without evidence of direct CNS microbial replication. Which mechanism fits?", "options": [{"text": "Hematogenous dissemination", "why": "Viremia, bacteremia, or fungemia can deliver organisms to CNS interfaces, crossing barriers or trafficking with infected cells."}, {"text": "Direct contiguous spread", "why": "Sinus, middle-ear, mastoid, skull, or dental infection can extend into nearby intracranial compartments."}, {"text": "Retrograde axonal transport", "why": "Some neurotropic pathogens travel from peripheral nerves toward neuronal cell bodies/CNS, as in rabies and herpes pathways."}, {"text": "Postinfectious autoimmune injury", "why": "Postinfectious immune injury can produce ADEM. Viral exposure is a trigger rather than necessarily the persistent agent in the lesion."}, {"text": "Direct traumatic or procedural inoculation", "why": "Penetrating injury or surgery can introduce organisms past normal protective barriers."}], "answer": 3, "image": null}, {"id": "Q099", "deck": "inf", "topic": "Bacterial inflammatory injury", "pages": [29], "page": 29, "ref": "slide-inf-29", "stem": "How can meningeal inflammation impair neurologic function even beyond direct bacterial injury?", "options": [{"text": "It affects only the external canal without CNS consequences", "why": "The inflammation here is intracranial."}, {"text": "Inflammatory edema and vascular/CSF disturbances can raise intracranial pressure", "why": "Subarachnoid inflammation disrupts normal physiology and can contribute to edema, ischemia, hydrocephalus, and altered consciousness."}, {"text": "Only lens opacity can alter consciousness", "why": "Brain inflammation and raised pressure can directly impair cognition/consciousness."}, {"text": "It necessarily lowers ICP to zero", "why": "Edema and impaired CSF handling can instead raise ICP."}, {"text": "It makes all neurologic deficits reversible immediately", "why": "Inflammatory and ischemic damage may persist."}], "answer": 1, "image": null}, {"id": "Q100", "deck": "inf", "topic": "Viral cellular injury", "pages": [20, 22], "page": 20, "ref": "slide-inf-20", "stem": "Why can different viruses produce different CNS syndromes despite similar entry routes?", "options": [{"text": "Season alone identifies the virus with certainty", "why": "Season can change pretest probability but does not replace clinical/microbiologic evaluation."}, {"text": "Every virus targets exactly the same cell type", "why": "Tropism is not identical across pathogens."}, {"text": "Only the skin is injured after CNS entry", "why": "CNS target-cell injury produces neurologic symptoms."}, {"text": "Viral CNS injury can never involve host inflammation", "why": "Both direct cytopathic and indirect inflammatory damage occur."}, {"text": "Cell and region tropism plus direct and immune-mediated injury vary", "why": "Viruses may target neurons, glia, or endothelium and different anatomic regions, changing presentation and imaging."}], "answer": 4, "image": null}, {"id": "Q101", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 20, 23], "page": 17, "ref": "slide-inf-17", "stem": "A school-age child has summer-onset aseptic meningitis with a lymphocytic CSF profile and positive enteroviral PCR. Which group is responsible?", "options": [{"text": "Western equine encephalitis virus", "why": "This mosquito-borne alphavirus is a listed arboviral encephalitis agent; exposure epidemiology and specific testing are needed to distinguish it."}, {"text": "Adenovirus", "why": "Adenovirus is a common conjunctival/respiratory pathogen and a less common listed aseptic CNS cause, not the defining temporal-lobe herpes pathogen."}, {"text": "Rabies virus", "why": "Rabies follows animal exposure and neural spread; encephalitic disease may include hydrophobia, agitation, autonomic features, or paralysis and is nearly always fatal after symptoms."}, {"text": "Nonpolio enteroviruses", "why": "Enteroviruses are common aseptic meningitis agents. Clinical syndrome alone does not specify every serotype, and early CSF may still be neutrophilic."}, {"text": "West Nile virus", "why": "A mosquito-borne flavivirus can cause meningitis, encephalitis, and acute flaccid paralysis from motor neuron involvement."}], "answer": 3, "image": null}, {"id": "Q102", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 25, 37], "page": 17, "ref": "slide-inf-17", "stem": "A febrile adult develops personality change, focal seizures, and a temporal lobe lesion with hemorrhagic features. Which virus is most likely?", "options": [{"text": "HSV-1", "why": "HSV-1 classically causes necrotizing temporal encephalitis. CSF PCR is useful; treatment should not be delayed while awaiting confirmation when suspicion is substantial."}, {"text": "West Nile virus", "why": "A mosquito-borne flavivirus can cause meningitis, encephalitis, and acute flaccid paralysis from motor neuron involvement."}, {"text": "Rabies virus", "why": "Rabies follows animal exposure and neural spread; encephalitic disease may include hydrophobia, agitation, autonomic features, or paralysis and is nearly always fatal after symptoms."}, {"text": "Poliovirus", "why": "Poliovirus can cause aseptic meningitis or asymmetric flaccid paralysis from anterior horn injury; paralysis is not present in every infection."}, {"text": "Western equine encephalitis virus", "why": "This mosquito-borne alphavirus is a listed arboviral encephalitis agent; exposure epidemiology and specific testing are needed to distinguish it."}], "answer": 0, "image": "figure-25.jpg"}, {"id": "Q103", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 21], "page": 17, "ref": "slide-inf-17", "stem": "Recurrent episodes of aseptic meningitis occur in a patient with HSV-2 detected in CSF. Which agent causes these episodes?", "options": [{"text": "HSV-2", "why": "HSV-2 can cause recurrent lymphocytic meningitis. A meningeal syndrome differs from the classic HSV-1 temporal-parenchymal presentation."}, {"text": "Varicella-zoster virus", "why": "VZV can cause meningitis/encephalitis or vasculopathy, sometimes without a rash; it is also a listed postinfectious trigger."}, {"text": "Adenovirus", "why": "Adenovirus is a common conjunctival/respiratory pathogen and a less common listed aseptic CNS cause, not the defining temporal-lobe herpes pathogen."}, {"text": "Rabies virus", "why": "Rabies follows animal exposure and neural spread; encephalitic disease may include hydrophobia, agitation, autonomic features, or paralysis and is nearly always fatal after symptoms."}, {"text": "HSV-1", "why": "This herpesvirus classically causes sporadic necrotizing temporal lobe encephalitis, with behavioral change, seizures, and possible hemorrhagic CSF."}], "answer": 0, "image": null}, {"id": "Q104", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 37], "page": 17, "ref": "slide-inf-17", "stem": "A patient develops encephalitis and cerebral vascular inflammation after shingles. Which virus is implicated?", "options": [{"text": "HIV", "why": "Acute HIV can cause an aseptic meningeal/encephalitic syndrome, while advanced HIV predisposes to distinct opportunistic CNS and retinal infections."}, {"text": "Western equine encephalitis virus", "why": "This mosquito-borne alphavirus is a listed arboviral encephalitis agent; exposure epidemiology and specific testing are needed to distinguish it."}, {"text": "Nonpolio enteroviruses", "why": "Echoviruses and Coxsackie viruses commonly cause aseptic meningitis and can also cause encephalitis, myelitis, or other syndromes depending on type."}, {"text": "Varicella-zoster virus", "why": "VZV can cause direct CNS infection and vasculopathy; a rash may help but is not mandatory in every neurologic case."}, {"text": "HSV-1", "why": "This herpesvirus classically causes sporadic necrotizing temporal lobe encephalitis, with behavioral change, seizures, and possible hemorrhagic CSF."}], "answer": 3, "image": null}, {"id": "Q105", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17], "page": 17, "ref": "slide-inf-17", "stem": "An underimmunized patient develops parotid swelling followed by aseptic meningitis. Which listed virus fits?", "options": [{"text": "Mumps virus", "why": "Mumps is a recognized viral meningitis cause. CNS involvement can also occur without obvious parotitis."}, {"text": "Eastern equine encephalitis virus", "why": "This mosquito-borne alphavirus can cause severe encephalitis; geography, vectors, season, and testing distinguish it from other arboviruses."}, {"text": "Poliovirus", "why": "Poliovirus can cause aseptic meningitis or asymmetric flaccid paralysis from anterior horn injury; paralysis is not present in every infection."}, {"text": "Measles virus", "why": "Measles is a listed trigger for postinfectious encephalomyelitis and can cause additional distinct neurologic complications; these should not all be conflated."}, {"text": "Nonpolio enteroviruses", "why": "Echoviruses and Coxsackie viruses commonly cause aseptic meningitis and can also cause encephalitis, myelitis, or other syndromes depending on type."}], "answer": 0, "image": null}, {"id": "Q106", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17], "page": 17, "ref": "slide-inf-17", "stem": "A pet-rodent owner develops a biphasic febrile illness and aseptic meningitis. Which rodent-associated virus should be considered?", "options": [{"text": "Influenza virus", "why": "Influenza can be associated with infection-triggered encephalopathy or postinfectious immune neurologic disease, not only pulmonary symptoms."}, {"text": "Eastern equine encephalitis virus", "why": "This mosquito-borne alphavirus can cause severe encephalitis; geography, vectors, season, and testing distinguish it from other arboviruses."}, {"text": "Lymphocytic choriomeningitis virus", "why": "LCMV is linked to rodent exposure. Exposure history can refine the viral differential when the CSF pattern is nonspecific."}, {"text": "Rabies virus", "why": "Rabies follows animal exposure and neural spread; encephalitic disease may include hydrophobia, agitation, autonomic features, or paralysis and is nearly always fatal after symptoms."}, {"text": "HSV-2", "why": "HSV-2 is a recognized cause of aseptic meningitis and can cause recurrent meningitis; it is not limited to genital skin disease."}], "answer": 2, "image": null}, {"id": "Q107", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 37], "page": 17, "ref": "slide-inf-17", "stem": "A patient has an acute retroviral illness with aseptic meningeal symptoms and newly confirmed infection. Which virus can itself cause this early CNS syndrome?", "options": [{"text": "Varicella-zoster virus", "why": "VZV can cause meningitis/encephalitis or vasculopathy, sometimes without a rash; it is also a listed postinfectious trigger."}, {"text": "HSV-1", "why": "This herpesvirus classically causes sporadic necrotizing temporal lobe encephalitis, with behavioral change, seizures, and possible hemorrhagic CSF."}, {"text": "Mumps virus", "why": "Mumps can cause aseptic meningitis with or without prominent parotitis and is a vaccine-preventable listed cause."}, {"text": "Lymphocytic choriomeningitis virus", "why": "LCMV is a rodent-associated arenavirus that can produce a biphasic illness and aseptic meningitis."}, {"text": "HIV", "why": "Acute HIV can produce aseptic meningitis/meningoencephalitis. This is separate from opportunistic infections resulting from advanced immune deficiency."}], "answer": 4, "image": null}, {"id": "Q108", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 27, 28, 37], "page": 17, "ref": "slide-inf-17", "stem": "Weeks after an animal bite, a patient develops bite-site paresthesia, agitation, and painful swallowing spasms triggered by water. Which virus is most likely?", "options": [{"text": "Varicella-zoster virus", "why": "VZV can cause meningitis/encephalitis or vasculopathy, sometimes without a rash; it is also a listed postinfectious trigger."}, {"text": "Rabies virus", "why": "Rabies can produce hydrophobia from pharyngeal spasms, followed by progressive neurologic disease. Hydrophobia is characteristic but not present in every case."}, {"text": "Lymphocytic choriomeningitis virus", "why": "LCMV is a rodent-associated arenavirus that can produce a biphasic illness and aseptic meningitis."}, {"text": "Adenovirus", "why": "Adenovirus is a common conjunctival/respiratory pathogen and a less common listed aseptic CNS cause, not the defining temporal-lobe herpes pathogen."}, {"text": "Influenza virus", "why": "Influenza can be associated with infection-triggered encephalopathy or postinfectious immune neurologic disease, not only pulmonary symptoms."}], "answer": 1, "image": null}, {"id": "Q109", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 26, 37], "page": 17, "ref": "slide-inf-17", "stem": "After mosquito exposure, an older patient develops encephalitis and asymmetric flaccid weakness due to anterior horn injury. Which listed arbovirus is especially associated?", "options": [{"text": "Adenovirus", "why": "Adenovirus is a common conjunctival/respiratory pathogen and a less common listed aseptic CNS cause, not the defining temporal-lobe herpes pathogen."}, {"text": "Nonpolio enteroviruses", "why": "Echoviruses and Coxsackie viruses commonly cause aseptic meningitis and can also cause encephalitis, myelitis, or other syndromes depending on type."}, {"text": "Varicella-zoster virus", "why": "VZV can cause meningitis/encephalitis or vasculopathy, sometimes without a rash; it is also a listed postinfectious trigger."}, {"text": "HIV", "why": "Acute HIV can cause an aseptic meningeal/encephalitic syndrome, while advanced HIV predisposes to distinct opportunistic CNS and retinal infections."}, {"text": "West Nile virus", "why": "West Nile neuroinvasive disease can combine meningoencephalitis and a polio-like motor syndrome. This is a nonpolio cause of acute flaccid paralysis."}], "answer": 4, "image": null}, {"id": "Q110", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 26], "page": 17, "ref": "slide-inf-17", "stem": "An unvaccinated patient develops asymmetric flaccid paralysis after a febrile gastrointestinal illness. Testing identifies poliovirus. Which pathogen is responsible?", "options": [{"text": "Mumps virus", "why": "Mumps can cause aseptic meningitis with or without prominent parotitis and is a vaccine-preventable listed cause."}, {"text": "Varicella-zoster virus", "why": "VZV can cause meningitis/encephalitis or vasculopathy, sometimes without a rash; it is also a listed postinfectious trigger."}, {"text": "West Nile virus", "why": "A mosquito-borne flavivirus can cause meningitis, encephalitis, and acute flaccid paralysis from motor neuron involvement."}, {"text": "Western equine encephalitis virus", "why": "This mosquito-borne alphavirus is a listed arboviral encephalitis agent; exposure epidemiology and specific testing are needed to distinguish it."}, {"text": "Poliovirus", "why": "Anterior horn motor neuron injury causes weakness, wasting, and hyporeflexia with relative sensory sparing. Poliovirus also causes nonparalytic/asymptomatic infections."}], "answer": 4, "image": null}, {"id": "Q111", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17, 19], "page": 17, "ref": "slide-inf-17", "stem": "A child develops an ADEM-like syndrome after measles. Which listed infection is the preceding trigger?", "options": [{"text": "Measles virus", "why": "Measles can trigger postinfectious immune demyelination. This mechanism is distinct from directly equating all measles CNS complications with ADEM."}, {"text": "HIV", "why": "Acute HIV can cause an aseptic meningeal/encephalitic syndrome, while advanced HIV predisposes to distinct opportunistic CNS and retinal infections."}, {"text": "HSV-1", "why": "This herpesvirus classically causes sporadic necrotizing temporal lobe encephalitis, with behavioral change, seizures, and possible hemorrhagic CSF."}, {"text": "Rabies virus", "why": "Rabies follows animal exposure and neural spread; encephalitic disease may include hydrophobia, agitation, autonomic features, or paralysis and is nearly always fatal after symptoms."}, {"text": "Influenza virus", "why": "Influenza can be associated with infection-triggered encephalopathy or postinfectious immune neurologic disease, not only pulmonary symptoms."}], "answer": 0, "image": null}, {"id": "Q112", "deck": "inf", "topic": "Viral pathogen recognition", "pages": [17], "page": 17, "ref": "slide-inf-17", "stem": "A patient develops postinfectious neurologic inflammation after influenza. Which listed virus is the antecedent trigger?", "options": [{"text": "Eastern equine encephalitis virus", "why": "This mosquito-borne alphavirus can cause severe encephalitis; geography, vectors, season, and testing distinguish it from other arboviruses."}, {"text": "HSV-2", "why": "HSV-2 is a recognized cause of aseptic meningitis and can cause recurrent meningitis; it is not limited to genital skin disease."}, {"text": "HSV-1", "why": "This herpesvirus classically causes sporadic necrotizing temporal lobe encephalitis, with behavioral change, seizures, and possible hemorrhagic CSF."}, {"text": "Influenza virus", "why": "Influenza can be associated with several infection-triggered neurologic syndromes. Defining the syndrome requires examination, imaging, and exclusion of active/alternative causes."}, {"text": "HIV", "why": "Acute HIV can cause an aseptic meningeal/encephalitic syndrome, while advanced HIV predisposes to distinct opportunistic CNS and retinal infections."}], "answer": 3, "image": null}, {"id": "Q113", "deck": "inf", "topic": "Enterovirus course", "pages": [23], "page": 23, "ref": "slide-inf-23", "stem": "Which feature is illustrated by the enterovirus time-course graph?", "options": [{"text": "A minor systemic phase may precede neurologic illness, while fecal shedding can outlast viremia", "why": "The source graph shows a possible biphasic illness and different detection windows in blood, throat, stool, and CSF. Its timeline is illustrative, not identical for all types."}, {"text": "All infections produce immediate paralysis on the first day", "why": "Many are asymptomatic or nonparalytic, and incubation/clinical progression varies."}, {"text": "Neutralizing antibody peaks before exposure", "why": "Antibody rises after infection rather than before initial exposure in a susceptible host."}, {"text": "A negative blood test at a later time excludes prior infection", "why": "Viremia can resolve while other evidence remains."}, {"text": "Virus must remain equally detectable in every specimen indefinitely", "why": "Detection changes with specimen and time."}], "answer": 0, "image": null}, {"id": "Q114", "deck": "inf", "topic": "Enterovirus syndromes", "pages": [23], "page": 23, "ref": "slide-inf-23", "stem": "Which spectrum is consistent with the enterovirus table?", "options": [{"text": "No CNS disease because they replicate initially outside the CNS", "why": "Peripheral entry does not prevent neuroinvasion."}, {"text": "Aseptic meningitis, encephalitis, paralysis, ataxia, cranial neuropathy, and selected chronic infections", "why": "Different enteroviruses can cause overlapping neurologic syndromes; a type-to-syndrome table is not a one-to-one rule."}, {"text": "Only pyogenic brain abscess", "why": "Enteroviruses do not define that suppurative category."}, {"text": "Only otitis externa", "why": "Enteroviruses have a much broader systemic/CNS spectrum."}, {"text": "Only retinitis in advanced HIV", "why": "That is a classic CMV context, not the full enterovirus spectrum."}], "answer": 1, "image": null}, {"id": "Q115", "deck": "inf", "topic": "Enterovirus classification", "pages": [23], "page": 23, "ref": "slide-inf-23", "stem": "The historical table lists enterovirus 72 as hepatitis A virus. What is the appropriate qualification?", "options": [{"text": "Hepatitis A is a herpesvirus", "why": "It is not a herpesvirus."}, {"text": "Hepatitis A virus is now classified in the genus Hepatovirus", "why": "The table preserves older nomenclature. Current classification should not treat HAV as a routine modern enterovirus CNS cause solely from that old label."}, {"text": "Every modern enterovirus is a hepatitis A subtype", "why": "Enterovirus and Hepatovirus are distinct genera."}, {"text": "Hepatitis A contains no nucleic acid", "why": "HAV is an RNA virus."}, {"text": "The historical label proves that HAV commonly causes all listed encephalitis cases", "why": "A historical classification does not establish clinical frequency."}], "answer": 1, "image": null}, {"id": "Q116", "deck": "inf", "topic": "Coxsackie clinical associations", "pages": [24], "page": 24, "ref": "slide-inf-24", "stem": "A child has fever, painful oral lesions, and vesicles on the hands and feet. Which association is most characteristic in the deck?", "options": [{"text": "Coxsackie A24-associated acute hemorrhagic conjunctivitis", "why": "Coxsackie A24 variant and enterovirus 70 can cause acute hemorrhagic conjunctivitis with outbreaks."}, {"text": "Coxsackie B-associated pleurodynia/myocarditis pattern", "why": "Coxsackie B types are particularly associated with painful chest/abdominal muscle illness and cardiac or systemic neonatal disease."}, {"text": "Enteroviral aseptic meningitis", "why": "Both Coxsackie groups and echoviruses can cause a febrile meningeal syndrome; serotype is not determined by neck stiffness alone."}, {"text": "Coxsackie A-associated hand-foot-mouth/herpangina pattern", "why": "HFMD and herpangina are classic Coxsackie A associations. The syndrome can also involve EV-A71 and other types, so the association is not exclusive."}, {"text": "Enterovirus-associated motor disease", "why": "Selected Coxsackie or other enterovirus types can cause sporadic paralysis; motor disease is not limited to poliovirus."}], "answer": 3, "image": null}, {"id": "Q117", "deck": "inf", "topic": "Coxsackie clinical associations", "pages": [24], "page": 24, "ref": "slide-inf-24", "stem": "A child has posterior oral vesicles and fever without a CNS deficit. Which listed pattern fits herpangina?", "options": [{"text": "Coxsackie A-associated hand-foot-mouth/herpangina pattern", "why": "Herpangina commonly involves Coxsackie A. It is an oral syndrome and does not automatically imply encephalitis."}, {"text": "Coxsackie A24-associated acute hemorrhagic conjunctivitis", "why": "Coxsackie A24 variant and enterovirus 70 can cause acute hemorrhagic conjunctivitis with outbreaks."}, {"text": "Enteroviral aseptic meningitis", "why": "Both Coxsackie groups and echoviruses can cause a febrile meningeal syndrome; serotype is not determined by neck stiffness alone."}, {"text": "Coxsackie B-associated pleurodynia/myocarditis pattern", "why": "Coxsackie B types are particularly associated with painful chest/abdominal muscle illness and cardiac or systemic neonatal disease."}, {"text": "Enterovirus-associated motor disease", "why": "Selected Coxsackie or other enterovirus types can cause sporadic paralysis; motor disease is not limited to poliovirus."}], "answer": 0, "image": null}, {"id": "Q118", "deck": "inf", "topic": "Coxsackie clinical associations", "pages": [24], "page": 24, "ref": "slide-inf-24", "stem": "An adult has abrupt fever and severe episodic chest-wall muscle pain during an enterovirus outbreak. Which association fits pleurodynia?", "options": [{"text": "Coxsackie A-associated hand-foot-mouth/herpangina pattern", "why": "Coxsackie A types commonly cause oral lesions or hand-foot-mouth disease; EV-A71 and other enteroviruses may also cause HFMD."}, {"text": "Coxsackie A24-associated acute hemorrhagic conjunctivitis", "why": "Coxsackie A24 variant and enterovirus 70 can cause acute hemorrhagic conjunctivitis with outbreaks."}, {"text": "Enteroviral aseptic meningitis", "why": "Both Coxsackie groups and echoviruses can cause a febrile meningeal syndrome; serotype is not determined by neck stiffness alone."}, {"text": "Coxsackie B-associated pleurodynia/myocarditis pattern", "why": "Coxsackie B is associated with pleurodynia and myocarditis. The table also lists neonatal disease, orchitis, and pancreatic associations."}, {"text": "Enterovirus-associated motor disease", "why": "Selected Coxsackie or other enterovirus types can cause sporadic paralysis; motor disease is not limited to poliovirus."}], "answer": 3, "image": null}, {"id": "Q119", "deck": "inf", "topic": "Coxsackie clinical associations", "pages": [24], "page": 24, "ref": "slide-inf-24", "stem": "An outbreak produces painful red eyes with subconjunctival hemorrhage and Coxsackie A24 variant is detected. Which association fits?", "options": [{"text": "Coxsackie A-associated hand-foot-mouth/herpangina pattern", "why": "Coxsackie A types commonly cause oral lesions or hand-foot-mouth disease; EV-A71 and other enteroviruses may also cause HFMD."}, {"text": "Coxsackie B-associated pleurodynia/myocarditis pattern", "why": "Coxsackie B types are particularly associated with painful chest/abdominal muscle illness and cardiac or systemic neonatal disease."}, {"text": "Coxsackie A24-associated acute hemorrhagic conjunctivitis", "why": "Acute hemorrhagic conjunctivitis is associated with Coxsackie A24 variant and enterovirus 70. It is distinct from a corneal ulcer."}, {"text": "Enterovirus-associated motor disease", "why": "Selected Coxsackie or other enterovirus types can cause sporadic paralysis; motor disease is not limited to poliovirus."}, {"text": "Enteroviral aseptic meningitis", "why": "Both Coxsackie groups and echoviruses can cause a febrile meningeal syndrome; serotype is not determined by neck stiffness alone."}], "answer": 2, "image": null}, {"id": "Q120", "deck": "inf", "topic": "Coxsackie clinical associations", "pages": [24], "page": 24, "ref": "slide-inf-24", "stem": "A patient has acute fever, headache, photophobia, and neck stiffness with Coxsackie virus detected in CSF. Which syndrome fits?", "options": [{"text": "Coxsackie A-associated hand-foot-mouth/herpangina pattern", "why": "Coxsackie A types commonly cause oral lesions or hand-foot-mouth disease; EV-A71 and other enteroviruses may also cause HFMD."}, {"text": "Enterovirus-associated motor disease", "why": "Selected Coxsackie or other enterovirus types can cause sporadic paralysis; motor disease is not limited to poliovirus."}, {"text": "Enteroviral aseptic meningitis", "why": "Coxsackie illness commonly includes meningitis and may fluctuate over days. New progressive lethargy, disorientation, or seizures suggest more serious parenchymal involvement."}, {"text": "Coxsackie B-associated pleurodynia/myocarditis pattern", "why": "Coxsackie B types are particularly associated with painful chest/abdominal muscle illness and cardiac or systemic neonatal disease."}, {"text": "Coxsackie A24-associated acute hemorrhagic conjunctivitis", "why": "Coxsackie A24 variant and enterovirus 70 can cause acute hemorrhagic conjunctivitis with outbreaks."}], "answer": 2, "image": null}, {"id": "Q121", "deck": "inf", "topic": "Coxsackie clinical associations", "pages": [17, 24, 26], "page": 17, "ref": "slide-inf-17", "stem": "A Coxsackie infection is followed by an acute flaccid motor syndrome. Which statement best captures the table association?", "options": [{"text": "Coxsackie A-associated hand-foot-mouth/herpangina pattern", "why": "Coxsackie A types commonly cause oral lesions or hand-foot-mouth disease; EV-A71 and other enteroviruses may also cause HFMD."}, {"text": "Enteroviral aseptic meningitis", "why": "Both Coxsackie groups and echoviruses can cause a febrile meningeal syndrome; serotype is not determined by neck stiffness alone."}, {"text": "Coxsackie A24-associated acute hemorrhagic conjunctivitis", "why": "Coxsackie A24 variant and enterovirus 70 can cause acute hemorrhagic conjunctivitis with outbreaks."}, {"text": "Coxsackie B-associated pleurodynia/myocarditis pattern", "why": "Coxsackie B types are particularly associated with painful chest/abdominal muscle illness and cardiac or systemic neonatal disease."}, {"text": "Enterovirus-associated motor disease", "why": "Selected nonpolio enteroviruses can cause motor disease. The source gives specific historical A-type examples; syndrome and confirmatory testing are more useful than assuming paralysis proves polio."}], "answer": 4, "image": null}, {"id": "Q122", "deck": "inf", "topic": "Coxsackie systemic associations", "pages": [24], "page": 24, "ref": "slide-inf-24", "stem": "Which group of non-CNS associations is emphasized for Coxsackie B in the lecture table?", "options": [{"text": "Neonatal systemic disease, pleurodynia, orchitis, and pancreatic associations", "why": "The table also includes carditis and rash in both groups. Associations are not proof of causation for every individual episode of diabetes or pancreatitis."}, {"text": "Only chronic fungal meningitis", "why": "Coxsackie viruses are not fungi."}, {"text": "Only CMV retinitis", "why": "CMV is a different virus with a different classic immune context."}, {"text": "Only herpangina and hand-foot-mouth disease", "why": "These are emphasized more for Coxsackie A in the table."}, {"text": "Only a fixed middle-ear air-bone gap", "why": "That does not represent the table’s systemic viral syndromes."}], "answer": 0, "image": null}, {"id": "Q123", "deck": "inf", "topic": "Rash interpretation", "pages": [24, 31], "page": 24, "ref": "slide-inf-24", "stem": "A febrile patient has a rash that does not blanch with pressure. Which interpretation is safest and most accurate?", "options": [{"text": "Petechiae cannot occur in meningococcal disease", "why": "They are a recognized invasive meningococcal finding."}, {"text": "Petechiae/purpura reflect bleeding into skin and require assessment for invasive disease", "why": "Such lesions may occur in several infections, including enteroviral illness, but fever with nonblanching rash raises urgent concern for meningococcemia and other serious causes."}, {"text": "Absence of blanching excludes sepsis", "why": "It can be an important sepsis warning sign."}, {"text": "The glass test proves Coxsackie infection", "why": "Nonblanching is not organism-specific."}, {"text": "Every blanching rash is harmless", "why": "Blanching alone does not establish benignity."}], "answer": 1, "image": null}, {"id": "Q124", "deck": "inf", "topic": "Rabies peripheral phase", "pages": [27, 28], "page": 27, "ref": "slide-inf-27", "stem": "Why can rabies postexposure prophylaxis work before symptoms begin?", "options": [{"text": "Peripheral incubation provides time for local antibody and active vaccine immunity before CNS disease", "why": "Wound care, exposure risk assessment, and indicated PEP act before established neurologic infection. Waiting for symptoms forfeits this preventive opportunity."}, {"text": "Natural antibody always fully protects before neural spread", "why": "A timely effective natural response cannot be assumed."}, {"text": "The vaccine reliably cures established symptomatic encephalitis", "why": "PEP prevents disease; it is not an established cure once neurologic rabies appears."}, {"text": "Rabies never enters nerves", "why": "Neural entry and transport are central to its pathogenesis."}, {"text": "Animal bites cannot transmit rabies until the wound becomes infected with bacteria", "why": "Rabies inoculation does not require secondary bacterial infection."}], "answer": 0, "image": null}, {"id": "Q125", "deck": "inf", "topic": "Rabies transport", "pages": [27], "page": 27, "ref": "slide-inf-27", "stem": "Which event follows local rabies inoculation and possible muscle replication?", "options": [{"text": "Direct conversion of muscle cells into brain tissue", "why": "This is not the transport mechanism."}, {"text": "Elimination by antibiotics targeting bacterial cell walls", "why": "Rabies is a virus and lacks a bacterial wall."}, {"text": "Immediate universal viremia as the only route", "why": "Rabies neuroinvasion is characteristically neural rather than ordinary hematogenous dissemination."}, {"text": "Entry into peripheral nerves followed by retrograde transport toward the CNS", "why": "Motor and sensory neural pathways can contribute. The slide’s dorsal-root-focused diagram is a simplified illustration, not an exclusive route."}, {"text": "Restriction of the virus permanently to the skin", "why": "Untreated infection can invade the CNS."}], "answer": 3, "image": null}, {"id": "Q126", "deck": "inf", "topic": "Rabies incubation", "pages": [27, 28], "page": 27, "ref": "slide-inf-27", "stem": "Which factors can affect the incubation period after rabies exposure?", "options": [{"text": "Inoculum and the exposure site’s relationship to neural pathways/CNS distance", "why": "Incubation is variable, often weeks to months, but can be shorter or longer. The slide’s 60–365-day table is not a strict boundary."}, {"text": "Only the appearance of a bacterial culture from the wound", "why": "Rabies progression is not determined solely by bacterial wound infection."}, {"text": "Only CSF neutrophil count on exposure day", "why": "CSF is not the routine determinant of exposure incubation risk."}, {"text": "A fixed one-year maximum in every person", "why": "Longer incubation is possible."}, {"text": "A fixed 60-day minimum in every person", "why": "Clinical incubation can be shorter."}], "answer": 0, "image": null}, {"id": "Q127", "deck": "inf", "topic": "Rabies prodrome", "pages": [28], "page": 28, "ref": "slide-inf-28", "stem": "Which symptoms may precede classic neurologic rabies?", "options": [{"text": "Only a bulging tympanic membrane", "why": "That suggests middle-ear infection, not the listed prodrome."}, {"text": "Only a unilateral corneal ulcer", "why": "That is not the characteristic rabies prodrome."}, {"text": "Fever, malaise, gastrointestinal symptoms, and pain or paresthesia at the bite site", "why": "The prodrome is nonspecific, but unusual sensations at the exposure site can be a clue before encephalitic or paralytic disease."}, {"text": "Only a stable old visual field defect", "why": "That does not capture acute evolving rabies symptoms."}, {"text": "Only an asymptomatic state forever", "why": "The prodrome marks the transition toward symptomatic disease."}], "answer": 2, "image": null}, {"id": "Q128", "deck": "inf", "topic": "Rabies hydrophobia", "pages": [28], "page": 28, "ref": "slide-inf-28", "stem": "What most directly explains hydrophobia in encephalitic rabies?", "options": [{"text": "Mechanical obstruction of the external auditory canal", "why": "That cannot explain pharyngeal spasms."}, {"text": "A definitive absence of CNS involvement", "why": "Hydrophobia is a neurologic disease feature."}, {"text": "A symptom present in every infected person during asymptomatic incubation", "why": "It occurs during clinical disease and is not universal."}, {"text": "A learned dislike of water without any motor abnormality", "why": "The characteristic symptom has a neurologic spasm basis."}, {"text": "Painful pharyngeal/inspiratory spasms provoked by attempts to swallow", "why": "Water-triggered swallowing spasms can produce apparent fear of drinking. Hydrophobia is characteristic but neither universal nor required in paralytic rabies."}], "answer": 4, "image": null}, {"id": "Q129", "deck": "inf", "topic": "Rabies late phase", "pages": [27, 28], "page": 27, "ref": "slide-inf-27", "stem": "Which sequence is compatible with progressive clinical rabies?", "options": [{"text": "Permanent confinement to muscle after neurologic symptoms", "why": "Neurologic symptoms imply CNS involvement."}, {"text": "Guaranteed complete recovery without treatment after hydrophobia", "why": "That is inconsistent with the grave prognosis of clinical rabies."}, {"text": "Predictable cure by wound washing after coma begins", "why": "Wound care is preventive early management, not a cure for established encephalitis."}, {"text": "Neurologic dysfunction followed by paralysis/coma and respiratory or autonomic failure", "why": "Seizures, hallucinations, disorientation, pharyngeal spasms, and paralysis can occur. Once symptoms appear, rabies is nearly always fatal, with rare exceptions."}, {"text": "No dissemination beyond brain at any stage", "why": "Virus can spread centrifugally to salivary glands and other tissues."}], "answer": 3, "image": null}, {"id": "Q130", "deck": "inf", "topic": "Rabies centrifugal spread", "pages": [27, 28], "page": 27, "ref": "slide-inf-27", "stem": "Why can saliva become infectious during rabies disease?", "options": [{"text": "The vaccine causes salivary gland infection", "why": "Proper rabies vaccine is preventive and does not cause this pathogenesis."}, {"text": "Every human antibody becomes a virion", "why": "Antibodies are not converted into virus."}, {"text": "Virus spreads from CNS through peripheral pathways to salivary glands", "why": "Centrifugal dissemination supports transmission by saliva. Clinical appearance alone does not replace exposure-specific public health assessment."}, {"text": "Only oral bacteria manufacture the virus", "why": "Rabies is a distinct viral infection."}, {"text": "CSF directly drains into saliva without tissue spread", "why": "Neural/organ dissemination, not direct CSF drainage, explains viral salivary involvement."}], "answer": 2, "image": null}, {"id": "Q131", "deck": "inf", "topic": "Rabies prophylaxis application", "pages": [27], "page": 27, "ref": "slide-inf-27", "stem": "An unvaccinated immunocompetent adult has an exposure for which rabies PEP is indicated. Which combination is appropriate in the CDC framework?", "options": [{"text": "Wound cleansing, rabies immune globulin, and a vaccine series", "why": "Passive antibody offers immediate local protection while vaccination induces active immunity. Previously vaccinated patients and immunocompromised patients have different details; dosing/placement follows current guidance."}, {"text": "No care because the bite has already healed", "why": "A healed wound does not by itself eliminate rabies risk."}, {"text": "Immune globulin alone with no active vaccination", "why": "An unvaccinated person generally needs both passive and active prophylaxis when PEP is indicated."}, {"text": "Vaccine only after hydrophobia begins", "why": "PEP should not be deferred until clinical disease."}, {"text": "Antibiotics alone", "why": "Antibiotics do not prevent rabies virus neuroinvasion."}], "answer": 0, "image": null}, {"id": "Q132", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [18, 32, 33, 37], "page": 18, "ref": "slide-inf-18", "stem": "An adult with advanced HIV has weeks of headache, high opening pressure, and positive CSF capsular antigen from an encapsulated yeast. Which pathogen fits?", "options": [{"text": "Blastomyces species", "why": "Blastomycosis can involve CNS after dissemination; broad-based budding yeast is a useful high-yield identification clue."}, {"text": "Sporothrix species", "why": "This dimorphic fungus can rarely cause chronic meningitis, especially with disseminated disease or immune impairment; CNS disease is not limited to common lymphocutaneous nodules."}, {"text": "Cryptococcus neoformans", "why": "Cryptococcus commonly causes subacute meningoencephalitis in this host. CSF can have few cells despite severe disease, and raised pressure is clinically important."}, {"text": "Mucorales", "why": "Broad pauciseptate hyphae with angioinvasion can cause rhino-orbital-cerebral disease, particularly with ketoacidosis or major immune impairment."}, {"text": "Candida species", "why": "Disseminated candidiasis can seed CNS parenchyma and form microabscesses; yeast and pseudohyphae distinguish it from angioinvasive molds."}], "answer": 2, "image": null}, {"id": "Q133", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [33, 37], "page": 33, "ref": "slide-inf-33", "stem": "A patient living in the desert Southwest has pulmonary fungal infection followed by chronic meningitis and hydrocephalus. Which fungus is a key concern?", "options": [{"text": "Aspergillus species", "why": "Septate acute-angle branching hyphae can invade vessels, causing hemorrhage/infarction and CNS masses or abscesses in susceptible hosts."}, {"text": "Sporothrix species", "why": "This dimorphic fungus can rarely cause chronic meningitis, especially with disseminated disease or immune impairment; CNS disease is not limited to common lymphocutaneous nodules."}, {"text": "Candida species", "why": "Disseminated candidiasis can seed CNS parenchyma and form microabscesses; yeast and pseudohyphae distinguish it from angioinvasive molds."}, {"text": "Histoplasma capsulatum", "why": "An endemic dimorphic fungus can disseminate, including chronic meningitis or focal CNS disease; tissue may show small intracellular yeasts."}, {"text": "Coccidioides species", "why": "Coccidioides can disseminate to meninges. Geographic exposure and chronic low-glucose CSF refine the differential but require specific confirmation."}], "answer": 4, "image": null}, {"id": "Q134", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [18, 33], "page": 18, "ref": "slide-inf-18", "stem": "A patient with candidemia develops multiple small CNS abscesses. Microscopy shows budding yeast and pseudohyphae. Which organism fits?", "options": [{"text": "Coccidioides species", "why": "An endemic dimorphic fungus of arid southwestern environments can disseminate from lung to cause chronic meningitis and hydrocephalus."}, {"text": "Candida species", "why": "Hematogenous Candida can invade parenchyma and produce microabscesses. This differs from a purely superficial colonization diagnosis."}, {"text": "Blastomyces species", "why": "Blastomycosis can involve CNS after dissemination; broad-based budding yeast is a useful high-yield identification clue."}, {"text": "Mucorales", "why": "Broad pauciseptate hyphae with angioinvasion can cause rhino-orbital-cerebral disease, particularly with ketoacidosis or major immune impairment."}, {"text": "Histoplasma capsulatum", "why": "An endemic dimorphic fungus can disseminate, including chronic meningitis or focal CNS disease; tissue may show small intracellular yeasts."}], "answer": 1, "image": null}, {"id": "Q135", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "A neutropenic patient has hemorrhagic cerebral lesions with vascular invasion by septate acute-angle branching hyphae. Which fungus fits?", "options": [{"text": "Candida species", "why": "Disseminated candidiasis can seed CNS parenchyma and form microabscesses; yeast and pseudohyphae distinguish it from angioinvasive molds."}, {"text": "Aspergillus species", "why": "Angioinvasion causes vascular injury, infarction, or hemorrhage. The deck emphasizes vascular and mass-forming manifestations of invasive molds."}, {"text": "Blastomyces species", "why": "Blastomycosis can involve CNS after dissemination; broad-based budding yeast is a useful high-yield identification clue."}, {"text": "Histoplasma capsulatum", "why": "An endemic dimorphic fungus can disseminate, including chronic meningitis or focal CNS disease; tissue may show small intracellular yeasts."}, {"text": "Mucorales", "why": "Broad pauciseptate hyphae with angioinvasion can cause rhino-orbital-cerebral disease, particularly with ketoacidosis or major immune impairment."}], "answer": 1, "image": null}, {"id": "Q136", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "A patient with diabetic ketoacidosis develops sinus infection, orbital involvement, and cerebral vascular invasion by broad pauciseptate hyphae. Which fungal group fits?", "options": [{"text": "Mucorales", "why": "Rhino-orbital-cerebral mucormycosis can spread contiguously and invade vessels. The older 'zygomycetes' table label is broader historical terminology."}, {"text": "Cryptococcus neoformans", "why": "An encapsulated yeast causes subacute/chronic meningoencephalitis, particularly in advanced HIV or other immunosuppression; CrAg is an important diagnostic test."}, {"text": "Sporothrix species", "why": "This dimorphic fungus can rarely cause chronic meningitis, especially with disseminated disease or immune impairment; CNS disease is not limited to common lymphocutaneous nodules."}, {"text": "Aspergillus species", "why": "Septate acute-angle branching hyphae can invade vessels, causing hemorrhage/infarction and CNS masses or abscesses in susceptible hosts."}, {"text": "Histoplasma capsulatum", "why": "An endemic dimorphic fungus can disseminate, including chronic meningitis or focal CNS disease; tissue may show small intracellular yeasts."}], "answer": 0, "image": null}, {"id": "Q137", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "A patient with disseminated fungal disease has small intracellular yeasts and chronic meningeal symptoms after relevant endemic exposure. Which listed agent fits?", "options": [{"text": "Candida species", "why": "Disseminated candidiasis can seed CNS parenchyma and form microabscesses; yeast and pseudohyphae distinguish it from angioinvasive molds."}, {"text": "Sporothrix species", "why": "This dimorphic fungus can rarely cause chronic meningitis, especially with disseminated disease or immune impairment; CNS disease is not limited to common lymphocutaneous nodules."}, {"text": "Blastomyces species", "why": "Blastomycosis can involve CNS after dissemination; broad-based budding yeast is a useful high-yield identification clue."}, {"text": "Histoplasma capsulatum", "why": "Histoplasma can involve CNS during dissemination. This is a supplemental organism-identification application of the fungal table."}, {"text": "Mucorales", "why": "Broad pauciseptate hyphae with angioinvasion can cause rhino-orbital-cerebral disease, particularly with ketoacidosis or major immune impairment."}], "answer": 3, "image": null}, {"id": "Q138", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "A disseminated fungal infection with broad-based budding yeast involves the CNS. Which listed genus is favored?", "options": [{"text": "Histoplasma capsulatum", "why": "An endemic dimorphic fungus can disseminate, including chronic meningitis or focal CNS disease; tissue may show small intracellular yeasts."}, {"text": "Aspergillus species", "why": "Septate acute-angle branching hyphae can invade vessels, causing hemorrhage/infarction and CNS masses or abscesses in susceptible hosts."}, {"text": "Cryptococcus neoformans", "why": "An encapsulated yeast causes subacute/chronic meningoencephalitis, particularly in advanced HIV or other immunosuppression; CrAg is an important diagnostic test."}, {"text": "Sporothrix species", "why": "This dimorphic fungus can rarely cause chronic meningitis, especially with disseminated disease or immune impairment; CNS disease is not limited to common lymphocutaneous nodules."}, {"text": "Blastomyces species", "why": "Broad-based budding is a high-yield Blastomyces clue. CNS involvement can be meningeal or focal, although less common than pulmonary disease."}], "answer": 4, "image": null}, {"id": "Q139", "deck": "inf", "topic": "Fungal CNS pathogens", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "A patient with disseminated sporotrichosis develops chronic meningitis. Which organism is responsible?", "options": [{"text": "Histoplasma capsulatum", "why": "An endemic dimorphic fungus can disseminate, including chronic meningitis or focal CNS disease; tissue may show small intracellular yeasts."}, {"text": "Coccidioides species", "why": "An endemic dimorphic fungus of arid southwestern environments can disseminate from lung to cause chronic meningitis and hydrocephalus."}, {"text": "Aspergillus species", "why": "Septate acute-angle branching hyphae can invade vessels, causing hemorrhage/infarction and CNS masses or abscesses in susceptible hosts."}, {"text": "Mucorales", "why": "Broad pauciseptate hyphae with angioinvasion can cause rhino-orbital-cerebral disease, particularly with ketoacidosis or major immune impairment."}, {"text": "Sporothrix species", "why": "Sporothrix is included in the table as an occasional meningeal cause. A familiar cutaneous association does not exclude disseminated CNS disease."}], "answer": 4, "image": null}, {"id": "Q140", "deck": "inf", "topic": "Fungal injury patterns", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "Which grouping correctly summarizes the major fungal CNS injury mechanisms in the deck?", "options": [{"text": "Only transient ciliary muscle spasm", "why": "That is not fungal CNS pathogenesis."}, {"text": "A requirement that every fungus produce identical CSF values", "why": "Profiles depend on pathogen, location, and host immunity."}, {"text": "Only external-ear irritation without deeper invasion", "why": "Fungi can cause serious CNS disease."}, {"text": "Only a sterile autoimmune response with no organism invasion", "why": "Direct fungal invasion is important in these conditions."}, {"text": "Chronic meningitis, vascular invasion, and parenchymal invasion/mass formation", "why": "Cryptococcus and Coccidioides emphasize meningitis, while invasive molds prominently involve vessels and focal masses. Organisms can overlap these categories."}], "answer": 4, "image": null}, {"id": "Q141", "deck": "inf", "topic": "Fungal table interpretation", "pages": [33], "page": 33, "ref": "slide-inf-33", "stem": "How should the table’s plus signs and labels such as common/occasional be interpreted?", "options": [{"text": "As evidence that all fungal cases are cryptococcal", "why": "The table includes several distinct organisms."}, {"text": "As exact population percentages", "why": "Plus signs are not percentage values."}, {"text": "As proof a fungus cannot cause a less-emphasized syndrome", "why": "The categories are not exclusive."}, {"text": "As a replacement for immune status and exposure history", "why": "Those factors remain central to diagnosis."}, {"text": "As qualitative source comparisons rather than precise universal incidence estimates", "why": "The table indicates tendencies toward meningitis or mass lesions. It does not provide a denominator, patient-specific risk, or current incidence for every region."}], "answer": 4, "image": null}, {"id": "Q142", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [9, 18, 35, 37], "page": 9, "ref": "slide-inf-9", "stem": "A patient with advanced HIV has subacute headache, focal weakness, and multiple ring-enhancing brain lesions, often involving basal ganglia. Which pathogen is a major concern?", "options": [{"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}, {"text": "Trypanosoma brucei", "why": "Tsetse-transmitted African trypanosomiasis can enter the CNS and cause sleep-cycle disturbance, cognitive change, and meningoencephalitis."}, {"text": "Toxoplasma gondii", "why": "Reactivation toxoplasmosis commonly causes focal encephalitis/abscess-like lesions. Primary CNS lymphoma and other infections remain alternatives; ring enhancement alone is not diagnostic."}, {"text": "Taenia solium larvae", "why": "Neurocysticercosis follows ingestion of eggs shed by a human tapeworm carrier; CNS larval cysts can cause seizures, inflammation, or hydrocephalus."}, {"text": "Balamuthia mandrillaris", "why": "This free-living ameba can cause granulomatous encephalitis, sometimes after skin or inhalational exposure and including immunocompetent people."}], "answer": 2, "image": null}, {"id": "Q143", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [18, 35, 37], "page": 18, "ref": "slide-inf-18", "stem": "A person from an endemic region develops seizures with parenchymal cysts, some showing a scolex and others calcified. Which pathogen fits?", "options": [{"text": "Balamuthia mandrillaris", "why": "This free-living ameba can cause granulomatous encephalitis, sometimes after skin or inhalational exposure and including immunocompetent people."}, {"text": "Plasmodium falciparum", "why": "Severe malaria can cause cerebral disease through infected erythrocyte sequestration and microvascular dysfunction, not a typical encysted brain abscess."}, {"text": "Taenia solium larvae", "why": "Neurocysticercosis can produce viable, degenerating, or calcified cysts. It is a larval cyst disease rather than an ordinary bacterial pus collection."}, {"text": "Trypanosoma brucei", "why": "Tsetse-transmitted African trypanosomiasis can enter the CNS and cause sleep-cycle disturbance, cognitive change, and meningoencephalitis."}, {"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}], "answer": 2, "image": null}, {"id": "Q144", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [18, 34], "page": 18, "ref": "slide-inf-18", "stem": "A previously healthy swimmer develops rapidly fatal meningoencephalitis after warm freshwater entered the nose. Which agent is most likely?", "options": [{"text": "Naegleria fowleri", "why": "Naegleria enters through nasal/olfactory pathways and causes PAM. The CSF can resemble bacterial meningitis with neutrophils and low glucose."}, {"text": "Trypanosoma brucei", "why": "Tsetse-transmitted African trypanosomiasis can enter the CNS and cause sleep-cycle disturbance, cognitive change, and meningoencephalitis."}, {"text": "Taenia solium larvae", "why": "Neurocysticercosis follows ingestion of eggs shed by a human tapeworm carrier; CNS larval cysts can cause seizures, inflammation, or hydrocephalus."}, {"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}, {"text": "Toxoplasma gondii", "why": "A protozoan can reactivate in advanced HIV, causing multiple enhancing focal brain lesions, and is important in retinochoroiditis."}], "answer": 0, "image": null}, {"id": "Q145", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [18, 37], "page": 18, "ref": "slide-inf-18", "stem": "An immunocompromised patient develops slowly progressive granulomatous encephalitis due to a free-living ameba also known for contact lens keratitis. Which organism fits?", "options": [{"text": "Balamuthia mandrillaris", "why": "This free-living ameba can cause granulomatous encephalitis, sometimes after skin or inhalational exposure and including immunocompetent people."}, {"text": "Taenia solium larvae", "why": "Neurocysticercosis follows ingestion of eggs shed by a human tapeworm carrier; CNS larval cysts can cause seizures, inflammation, or hydrocephalus."}, {"text": "Plasmodium falciparum", "why": "Severe malaria can cause cerebral disease through infected erythrocyte sequestration and microvascular dysfunction, not a typical encysted brain abscess."}, {"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}, {"text": "Acanthamoeba species", "why": "Acanthamoeba can cause granulomatous amebic encephalitis and keratitis, with different entry routes and host contexts."}], "answer": 4, "image": null}, {"id": "Q146", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [18], "page": 18, "ref": "slide-inf-18", "stem": "A patient has a preceding skin lesion followed by granulomatous amebic encephalitis; testing identifies Balamuthia. Which organism is responsible?", "options": [{"text": "Trypanosoma brucei", "why": "Tsetse-transmitted African trypanosomiasis can enter the CNS and cause sleep-cycle disturbance, cognitive change, and meningoencephalitis."}, {"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}, {"text": "Balamuthia mandrillaris", "why": "Balamuthia can enter through skin or respiratory routes and cause CNS disease, including in people without major immune suppression."}, {"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}, {"text": "Naegleria fowleri", "why": "Warm freshwater entering the nose can lead to fulminant primary amebic meningoencephalitis, often with neutrophilic CSF and possible motile trophozoites."}], "answer": 2, "image": null}, {"id": "Q147", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [37], "page": 37, "ref": "slide-inf-37", "stem": "A patient with dog-associated exposure develops a large cerebral hydatid cyst. Which parasite is implicated?", "options": [{"text": "Toxoplasma gondii", "why": "A protozoan can reactivate in advanced HIV, causing multiple enhancing focal brain lesions, and is important in retinochoroiditis."}, {"text": "Plasmodium falciparum", "why": "Severe malaria can cause cerebral disease through infected erythrocyte sequestration and microvascular dysfunction, not a typical encysted brain abscess."}, {"text": "Echinococcus granulosus", "why": "Hydatid disease results from the larval stage after egg ingestion. Avoiding rupture is an important procedural concern; it is distinct from a pyogenic abscess."}, {"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}, {"text": "Naegleria fowleri", "why": "Warm freshwater entering the nose can lead to fulminant primary amebic meningoencephalitis, often with neutrophilic CSF and possible motile trophozoites."}], "answer": 2, "image": null}, {"id": "Q148", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [37], "page": 37, "ref": "slide-inf-37", "stem": "A traveler has severe malaria, impaired consciousness, and parasitized red cells. Which organism listed in the deck is most associated with cerebral malaria?", "options": [{"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}, {"text": "Taenia solium larvae", "why": "Neurocysticercosis follows ingestion of eggs shed by a human tapeworm carrier; CNS larval cysts can cause seizures, inflammation, or hydrocephalus."}, {"text": "Naegleria fowleri", "why": "Warm freshwater entering the nose can lead to fulminant primary amebic meningoencephalitis, often with neutrophilic CSF and possible motile trophozoites."}, {"text": "Toxoplasma gondii", "why": "A protozoan can reactivate in advanced HIV, causing multiple enhancing focal brain lesions, and is important in retinochoroiditis."}, {"text": "Plasmodium falciparum", "why": "Infected erythrocyte sequestration and microvascular dysfunction contribute to cerebral malaria. This is not a typical focal larval cyst infection."}], "answer": 4, "image": null}, {"id": "Q149", "deck": "inf", "topic": "Parasitic and amebic CNS disease", "pages": [37], "page": 37, "ref": "slide-inf-37", "stem": "After tsetse exposure in sub-Saharan Africa, a patient develops progressive sleep disturbance and meningoencephalitis. Which organism fits?", "options": [{"text": "Trypanosoma brucei", "why": "African trypanosomiasis can progress from systemic infection to CNS involvement. Geography, exposure, parasite detection, and staging guide evaluation."}, {"text": "Naegleria fowleri", "why": "Warm freshwater entering the nose can lead to fulminant primary amebic meningoencephalitis, often with neutrophilic CSF and possible motile trophozoites."}, {"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}, {"text": "Plasmodium falciparum", "why": "Severe malaria can cause cerebral disease through infected erythrocyte sequestration and microvascular dysfunction, not a typical encysted brain abscess."}, {"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}], "answer": 0, "image": null}, {"id": "Q150", "deck": "inf", "topic": "Neurocysticercosis transmission", "pages": [35, 37], "page": 35, "ref": "slide-inf-35", "stem": "Which exposure directly causes human cysticercosis?", "options": [{"text": "A mosquito inoculates Taenia larvae into blood", "why": "Taenia solium is not mosquito transmitted."}, {"text": "Swimming with freshwater entering the nose", "why": "That is the classic Naegleria exposure, not cysticercosis."}, {"text": "A dog bite transmits rabies and Taenia by the same route", "why": "Rabies exposure is distinct from fecal-oral Taenia eggs."}, {"text": "Ingestion of pork cysticerci as the direct cause of CNS cysts", "why": "That primarily causes an adult intestinal tapeworm; the tissue disease route is egg ingestion."}, {"text": "Ingestion of Taenia solium eggs from fecal contamination by a human tapeworm carrier", "why": "Eggs release larvae that invade tissues. Eating pork containing cysticerci instead produces intestinal taeniasis, not direct tissue cysticercosis."}], "answer": 4, "image": null}, {"id": "Q151", "deck": "inf", "topic": "Parasitic CSF exceptions", "pages": [34], "page": 34, "ref": "slide-inf-34", "stem": "Which statement best corrects the broad claim that parasites usually produce CSF eosinophilia?", "options": [{"text": "Normal CSF always excludes a parenchymal parasitic lesion", "why": "Focal disease may not produce a strong meningeal CSF response."}, {"text": "Eosinophilia is most helpful for selected helminths and is not universal across parasites", "why": "Naegleria can be neutrophilic, other protozoal cases can be lymphocytic, and a focal parenchymal infection may have little CSF inflammation."}, {"text": "Every Toxoplasma brain lesion must produce predominantly eosinophilic CSF", "why": "This is not a reliable toxoplasmosis rule."}, {"text": "Eosinophils identify the exact parasite without exposure history", "why": "Several infectious and noninfectious conditions can cause eosinophilia."}, {"text": "Naegleria can never have neutrophils", "why": "PAM often has a neutrophilic pattern."}], "answer": 1, "image": null}, {"id": "Q152", "deck": "inf", "topic": "Abscess versus cyst", "pages": [18, 35], "page": 18, "ref": "slide-inf-18", "stem": "Why should Taenia solium not be treated as simply another routine pyogenic brain-abscess organism?", "options": [{"text": "It is a bacterium with the same cell wall as streptococci", "why": "Taenia is a cestode parasite."}, {"text": "Every ring-enhancing lesion has identical treatment", "why": "Etiology, location, burden, and lesion stage change management."}, {"text": "It cannot cause seizures", "why": "Seizures are a common manifestation."}, {"text": "It causes larval cysticercosis with stage- and location-dependent inflammation", "why": "Degenerating cysts can enhance and cause seizures, but their biology and management differ from a bacterial pus collection."}, {"text": "It causes only external canal infection", "why": "Neurocysticercosis affects CNS tissues/compartments."}], "answer": 3, "image": null}, {"id": "Q153", "deck": "inf", "topic": "Prion differential", "pages": [37], "page": 37, "ref": "slide-inf-37", "stem": "A patient develops rapidly progressive dementia, myoclonus, and ataxia without a typical inflammatory CSF profile. Which listed agent class can produce disease through protein misfolding?", "options": [{"text": "Enteroviruses", "why": "These are RNA viruses that can cause aseptic inflammatory CNS syndromes."}, {"text": "Neisseria meningitidis", "why": "This is a bacterium causing acute pyogenic meningitis/bacteremia."}, {"text": "Taenia solium", "why": "This is a larval cestode infection causing cysticercosis."}, {"text": "Cryptococcus", "why": "This is an encapsulated yeast associated with meningeal infection."}, {"text": "Prions", "why": "Prion propagation involves misfolded protein, not a conventional bacterium or virus. Spongiform neurodegeneration is distinct from the deck’s usual inflammatory meningitis/encephalitis patterns."}], "answer": 4, "image": null}, {"id": "Q154", "deck": "inf", "topic": "Arboviral pathogen list", "pages": [17, 37], "page": 17, "ref": "slide-inf-17", "stem": "Which pair from the final pathogen list consists of mosquito-borne alphaviruses associated with encephalitis?", "options": [{"text": "Eastern and Western equine encephalitis viruses", "why": "Both are arboviral encephalitis agents. West Nile is also mosquito-borne but belongs to a different viral family/genus grouping."}, {"text": "HSV-1 and HSV-2", "why": "These are herpesviruses, not mosquito-borne alphaviruses."}, {"text": "HIV and CMV", "why": "These are not the mosquito-borne alphaviruses asked about."}, {"text": "Rabies and LCMV", "why": "These have mammalian/rodent exposure pathways and are not the equine alphavirus pair."}, {"text": "Mumps and parainfluenza viruses", "why": "These are respiratory-associated paramyxovirus groups, not equine alphaviruses."}], "answer": 0, "image": null}, {"id": "Q155", "deck": "inf", "topic": "Listed postinfectious triggers", "pages": [17], "page": 17, "ref": "slide-inf-17", "stem": "Which set contains the postinfectious encephalitis/demyelination triggers listed in the source?", "options": [{"text": "Only Pseudomonas and Staphylococcus", "why": "Those are not the listed postinfectious viral set."}, {"text": "Only Taenia and Echinococcus", "why": "Those are helminthic cyst diseases rather than this viral trigger list."}, {"text": "Only Neisseria and pneumococcus", "why": "Those are acute pyogenic meningitis agents."}, {"text": "Only Cryptococcus and Coccidioides", "why": "Those are fungi associated with direct CNS infection."}, {"text": "Measles, mumps, rubella, varicella-zoster, and influenza", "why": "These infections are listed as possible preceding triggers. Not every neurologic syndrome after these infections is ADEM or necessarily caused by persistent CNS replication."}], "answer": 4, "image": null}, {"id": "Q156", "deck": "inf", "topic": "Aseptic pathogen list", "pages": [17], "page": 17, "ref": "slide-inf-17", "stem": "Which set contains additional viral meningitis agents explicitly listed in the deck?", "options": [{"text": "Candida, Aspergillus, and Mucorales", "why": "These are fungal agents."}, {"text": "Listeria, pneumococcus, and E. coli", "why": "These are bacterial rather than viral agents."}, {"text": "Taenia, Echinococcus, and Plasmodium", "why": "These are parasitic agents."}, {"text": "Prions only", "why": "Prions are not conventional viruses and typically do not cause inflammatory aseptic meningitis."}, {"text": "Adenovirus, mumps, LCMV, and parainfluenza types 2/3", "why": "The list complements common enteroviruses and HSV-2. A list association does not mean all agents are equally frequent in every age group."}], "answer": 4, "image": null}, {"id": "Q157", "deck": "inf", "topic": "Intracranial collection microbiology", "pages": [18, 36], "page": 18, "ref": "slide-inf-18", "stem": "Which microbial pattern is compatible with intracranial empyema spreading from sinus/skull infection?", "options": [{"text": "A requirement that every case contain only Neisseria", "why": "Empyema is not restricted to meningococcus."}, {"text": "A single identical organism in every geographic setting", "why": "Source and host context affect microbiology."}, {"text": "Only respiratory viruses without possible bacterial involvement", "why": "Suppurative collections commonly involve bacteria."}, {"text": "A requirement that every collection be a Taenia larval cyst", "why": "A cysticercus is biologically distinct from purulent empyema."}, {"text": "Mixed flora including streptococci, staphylococci, and anaerobes", "why": "Organisms depend on source, trauma/surgery, and host. Anaerobic gram-negative organisms can be included; fungal causes occur in selected hosts rather than every case."}], "answer": 4, "image": null}, {"id": "Q158", "deck": "inf", "topic": "Diagnostic urgency", "pages": [19, 21, 29, 31], "page": 19, "ref": "slide-inf-19", "stem": "Bacterial meningitis is strongly suspected, but lumbar puncture will be delayed. Which approach is appropriate?", "options": [{"text": "Assume normal initial blood tests exclude CNS infection", "why": "Routine blood results are not sufficient to rule it out."}, {"text": "Wait until every CSF test is final before treatment", "why": "This can dangerously postpone therapy."}, {"text": "Treat only if all classic meningeal signs are present", "why": "Their absence does not safely exclude disease."}, {"text": "Obtain blood cultures promptly if feasible and start empiric therapy without waiting for delayed LP", "why": "Diagnostic sampling is valuable, but suspected bacterial meningitis requires time-sensitive treatment. Imaging or procedural delay should not delay antibiotics."}, {"text": "Delay treatment for a repeat visit several days later", "why": "The suspected acute bacterial syndrome warrants urgent care."}], "answer": 3, "image": null}, {"id": "Q159", "deck": "inf", "topic": "Diagnostic urgency", "pages": [25, 35, 36], "page": 25, "ref": "slide-inf-25", "stem": "A patient with suspected intracranial abscess has focal deficits and papilledema. What should precede consideration of LP?", "options": [{"text": "A normal external ear examination as proof no abscess exists", "why": "A brain abscess can occur without visible external-ear disease."}, {"text": "Reassurance because all ring lesions are benign", "why": "Abscess and other mass lesions can be life threatening."}, {"text": "Automatic immediate LP in every patient with fever", "why": "Possible mass effect changes procedural safety."}, {"text": "An isolated surface eye swab as the complete evaluation", "why": "This does not assess intracranial mass effect."}, {"text": "Urgent neuroimaging and evaluation for mass effect or other LP contraindications", "why": "A mass lesion may create dangerous pressure gradients. LP is often unhelpful or unsafe in focal abscess; imaging and specialist/source-directed evaluation take priority."}], "answer": 4, "image": null}, {"id": "Q160", "deck": "inf", "topic": "Diagnostic evidence limits", "pages": [20, 21, 30, 32, 34], "page": 20, "ref": "slide-inf-20", "stem": "Which statement about negative CSF tests is most accurate?", "options": [{"text": "Any negative multiplex result excludes all infections", "why": "Panels do not cover every pathogen and sensitivity is not perfect."}, {"text": "A negative Gram stain excludes TB, fungi, and viruses", "why": "These require organism-appropriate tests and may not be visible on routine Gram stain."}, {"text": "Sensitivity depends on timing, specimen, organism, and prior treatment", "why": "A negative test or a panel lacking the organism cannot exclude every CNS infection. Interpretation should integrate clinical syndrome and exposure/host information."}, {"text": "A normal cell count always excludes severe infection in immune suppression", "why": "The immune response can be blunted."}, {"text": "One positive antibody to a remote infection proves active CNS disease", "why": "Past exposure and active neuroinvasion are not equivalent."}], "answer": 2, "image": null}, {"id": "Q161", "deck": "inf", "topic": "Extended eye and ear cases", "pages": [4, 5], "page": 4, "ref": "slide-inf-4", "stem": "A 27-year-old contact lens wearer develops progressive severe pain in one eye after a weekend of swimming. He admits rinsing his lenses and case with tap water. The eye is markedly photophobic, and examination shows a corneal ring infiltrate. The degree of pain seems greater than expected from the initial surface findings. A standard short antibacterial course has not helped. Which pathogen is particularly important to investigate, while recognizing that exposure and morphology do not by themselves provide definitive microbiologic identification?", "options": [{"text": "Streptococcus pneumoniae", "why": "An encapsulated gram-positive diplococcus can cause conjunctivitis, keratitis, otitis media, and meningitis rather than being restricted to one site."}, {"text": "Corynebacterium diphtheriae", "why": "This organism is a less common cause of membranous conjunctivitis in the appropriate clinical context, not the usual viral pink-eye agent."}, {"text": "Adenovirus", "why": "This common cause of contagious watery conjunctivitis can accompany pharyngitis and preauricular nodes; it is not a bacterium producing a Gram stain isolate."}, {"text": "Herpes simplex virus", "why": "HSV can cause recurrent dendritic epithelial keratitis or anterior uveitis. HSV-1 also causes temporal lobe encephalitis, while HSV-2 is associated with aseptic meningitis."}, {"text": "Acanthamoeba species", "why": "Water-contaminated lens practices, severe pain, and a ring infiltrate are characteristic Acanthamoeba clues. Corneal evaluation and organism-directed diagnostics are needed; this is not routine superficial conjunctivitis."}], "answer": 4, "image": null}, {"id": "Q162", "deck": "inf", "topic": "Extended eye and ear cases", "pages": [8, 9], "page": 8, "ref": "slide-inf-8", "stem": "A 41-year-old man with untreated advanced HIV reports new floaters, blurred vision, and a dark region in one visual field. His CD4 count is 19/µL. He has little external redness or discharge, but dilated examination shows expanding pale necrotic retinal areas with associated hemorrhage. The clinician explains that a positive blood viral test alone would not establish the ocular cause and arranges urgent retinal assessment. Which organism best fits the immune context and posterior-segment findings?", "options": [{"text": "Staphylococcus aureus", "why": "This skin-associated gram-positive organism can cause bacterial conjunctivitis, keratitis, and otitis externa; culture/context distinguish it from other bacteria."}, {"text": "Toxoplasma gondii", "why": "This protozoan is a major infectious cause of posterior retinochoroiditis and can reactivate as focal encephalitis in advanced HIV; it is not a fungus."}, {"text": "Cytomegalovirus", "why": "CMV retinitis is especially associated with profound cellular immune deficiency. The retinal lesion, not a nonspecific surface symptom or blood PCR alone, establishes the clinical concern. Prompt treatment assessment protects remaining vision."}, {"text": "Acanthamoeba species", "why": "Water exposure with contact lenses, severe pain out of proportion, and a ring infiltrate suggest amebic keratitis, including in otherwise healthy people."}, {"text": "Aspergillus species", "why": "This mold can cause fungal keratitis, otomycosis, or angioinvasive CNS disease in susceptible hosts."}], "answer": 2, "image": null}, {"id": "Q163", "deck": "inf", "topic": "Extended eye and ear cases", "pages": [11, 12, 13, 14], "page": 11, "ref": "slide-inf-11", "stem": "A 2-year-old develops fever, irritability, poor sleep, and deep right ear pain several days after a respiratory illness. The parent reports that the child seems to hear less clearly. The external canal is not notably swollen, and moving the auricle does not reproduce the severe pain. Pneumatic otoscopy reveals an opaque bulging tympanic membrane with markedly reduced movement. Which diagnosis best explains how the respiratory illness led to fluid accumulation, pressure, and a conductive hearing problem?", "options": [{"text": "Otitis media with effusion", "why": "Middle-ear fluid without acute infectious symptoms is OME; fluid alone does not establish acute otitis media."}, {"text": "Acute otitis media", "why": "Upper-airway inflammation can impair Eustachian ventilation, promoting middle-ear stasis and infection. Acute symptoms plus a bulging poorly mobile drum distinguish AOM from isolated canal infection and from a nonacute effusion."}, {"text": "Necrotizing otitis externa", "why": "Severe persistent otalgia with granulation tissue, especially in a diabetic/immunocompromised host, raises concern for invasive canal/skull-base infection."}, {"text": "Otomycosis", "why": "Fungal external canal disease often causes itching, debris, and discharge; Aspergillus and Candida are important organisms."}, {"text": "Acute otitis externa", "why": "Inflamed edematous external canal with pain on tragal pressure or auricle movement suggests AOE; canal obstruction can cause conductive loss."}], "answer": 1, "image": null}, {"id": "Q164", "deck": "inf", "topic": "Extended CNS cases", "pages": [18, 19, 21, 29, 30, 31], "page": 18, "ref": "slide-inf-18", "stem": "A 20-year-old student develops fever, severe headache, photophobia, and neck stiffness over several hours. He becomes drowsy and has scattered nonblanching petechiae. After urgent assessment, CSF is obtained: 4,500 WBC/µL with neutrophil predominance, protein 310 mg/dL, and glucose 18 mg/dL with concurrent serum glucose 90 mg/dL. The team does not wait for final cultures before starting treatment. Which broad CSF category best fits this rapidly evolving syndrome and laboratory profile?", "options": [{"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Chronic lymphocytic inflammation, high protein, and often low glucose can occur; advanced immunosuppression may produce surprisingly few cells."}, {"text": "Acute pyogenic bacterial pattern", "why": "The ratio is 0.20 with marked neutrophilic inflammation and high protein. Invasive meningococcal disease is a concern given the rash/context, but the pattern alone does not identify the organism. Prompt empiric therapy is essential."}, {"text": "Tuberculous meningitis pattern", "why": "A subacute/chronic illness with lymphocytes, high protein, and low glucose suggests TB; smear is insensitive and culture/NAAT improve detection."}, {"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}], "answer": 2, "image": null}, {"id": "Q165", "deck": "inf", "topic": "Extended CNS cases", "pages": [18, 32, 33, 34], "page": 18, "ref": "slide-inf-18", "stem": "A patient receiving intense immunosuppression develops several weeks of headache and nausea. There is no dramatic neck stiffness, and the peripheral blood count is not striking. Lumbar puncture, performed after appropriate assessment, shows high opening pressure, modest lymphocytes, increased protein, and reduced glucose. CSF antigen testing identifies an encapsulated yeast. Which category best describes this profile and explains why a limited cellular response should not falsely reassure the clinician?", "options": [{"text": "Neurosyphilitic pattern", "why": "CSF often has mild lymphocytic pleocytosis, modest protein elevation, and relatively preserved glucose; clinical context and syphilis-specific testing are essential."}, {"text": "Acute pyogenic bacterial pattern", "why": "Neutrophilic pleocytosis, markedly increased protein, and low CSF:serum glucose ratio favor bacterial meningitis, but exceptions and pretreatment effects occur."}, {"text": "Helminth-associated eosinophilic pattern", "why": "CSF eosinophilia suggests certain parasitic infections, especially helminths, but is not universal for protozoal or all parasitic CNS disease."}, {"text": "Typical viral pattern", "why": "Lymphocytic pleocytosis, modest protein elevation, and usually preserved glucose favor viral infection; early neutrophils and pathogen-specific exceptions are possible."}, {"text": "Cryptococcal or other fungal meningitis pattern", "why": "Cryptococcus can produce severe meningoencephalitis with little CSF pleocytosis in an immunocompromised host. Opening pressure and organism-specific antigen findings are crucial; a mild cell count is not evidence of trivial disease."}], "answer": 4, "image": null}, {"id": "Q166", "deck": "inf", "topic": "Extended CNS cases", "pages": [17, 19, 20, 21, 25, 37], "page": 17, "ref": "slide-inf-17", "stem": "A 46-year-old previously healthy adult develops fever and headache, then becomes unusually irritable and forgetful. Over the next day he has a focal seizure and difficulty naming objects. MRI shows a temporal lobe abnormality with hemorrhagic features, illustrated here. CSF has lymphocytes, increased protein, and some erythrocytes. The clinician interprets the red cells cautiously because a traumatic tap is also possible, but the clinical and imaging pattern strongly suggests a treatable neurotropic infection. Which virus is most likely?", "options": [{"text": "Measles virus", "why": "Measles is a listed trigger for postinfectious encephalomyelitis and can cause additional distinct neurologic complications; these should not all be conflated."}, {"text": "Varicella-zoster virus", "why": "VZV can cause meningitis/encephalitis or vasculopathy, sometimes without a rash; it is also a listed postinfectious trigger."}, {"text": "Eastern equine encephalitis virus", "why": "This mosquito-borne alphavirus can cause severe encephalitis; geography, vectors, season, and testing distinguish it from other arboviruses."}, {"text": "Western equine encephalitis virus", "why": "This mosquito-borne alphavirus is a listed arboviral encephalitis agent; exposure epidemiology and specific testing are needed to distinguish it."}, {"text": "HSV-1", "why": "Temporal parenchymal injury with behavioral change and seizures is characteristic of HSV-1 encephalitis. CSF PCR supports diagnosis; hemorrhagic CSF can occur but is neither required nor specific by itself."}], "answer": 4, "image": "figure-25.jpg"}, {"id": "Q167", "deck": "inf", "topic": "Extended CNS cases", "pages": [17, 27, 28, 37], "page": 17, "ref": "slide-inf-17", "stem": "A traveler was bitten by a dog and did not seek exposure assessment. Several weeks later he develops fever, malaise, and tingling around the healed bite. This progresses to agitation, confusion, and painful spasms when he attempts to drink water. Family members initially assume that the healed skin means the original exposure is no longer relevant. Which virus best explains the delayed progression from a peripheral inoculation site to an encephalitic syndrome through neural transport?", "options": [{"text": "Rabies virus", "why": "Rabies can incubate after wound healing, then enter neural pathways and cause devastating CNS disease. Water-triggered pharyngeal spasms are characteristic; prophylaxis acts before symptoms and is not replaced by waiting for clinical illness."}, {"text": "Adenovirus", "why": "Adenovirus is a common conjunctival/respiratory pathogen and a less common listed aseptic CNS cause, not the defining temporal-lobe herpes pathogen."}, {"text": "Mumps virus", "why": "Mumps can cause aseptic meningitis with or without prominent parotitis and is a vaccine-preventable listed cause."}, {"text": "Poliovirus", "why": "Poliovirus can cause aseptic meningitis or asymmetric flaccid paralysis from anterior horn injury; paralysis is not present in every infection."}, {"text": "Measles virus", "why": "Measles is a listed trigger for postinfectious encephalomyelitis and can cause additional distinct neurologic complications; these should not all be conflated."}], "answer": 0, "image": null}, {"id": "Q168", "deck": "inf", "topic": "Extended CNS cases", "pages": [16, 17, 19], "page": 16, "ref": "slide-inf-16", "stem": "A 9-year-old recovers from a febrile respiratory illness and returns to school. About two weeks later, he develops reduced alertness, unsteady walking, and weakness affecting different limbs. Fever is now mild. MRI shows large multifocal white-matter abnormalities rather than an isolated hemorrhagic temporal lesion. Infectious and other alternative causes are being evaluated, but the overall pattern suggests an immune-mediated response after the original illness. Which syndrome best fits the mechanism and anatomic distribution?", "options": [{"text": "Encephalitis", "why": "Brain parenchymal inflammation causes altered mental status, seizures, focal findings, and supportive CSF/MRI/EEG evidence rather than only meningeal irritation."}, {"text": "Acute transverse myelitis", "why": "Cord inflammation produces bilateral motor and sensory deficits with a sensory level and autonomic dysfunction; symmetry can vary and early spinal shock can be flaccid."}, {"text": "Acute disseminated encephalomyelitis", "why": "ADEM is a postinfectious inflammatory demyelinating syndrome with encephalopathy and multifocal deficits. It is not simply direct viral multiplication in neurons, and not every postinfectious encephalopathy is ADEM."}, {"text": "Meningoencephalitis", "why": "Combined meningeal and parenchymal involvement can produce both neck stiffness/headache and sustained altered behavior, seizures, or focal deficits."}, {"text": "Acute flaccid myelitis", "why": "Acute anterior horn/spinal gray-matter injury can produce flaccid weakness and reduced reflexes, often with relatively spared sensation; not all cases are poliovirus."}], "answer": 2, "image": null}, {"id": "Q169", "deck": "inf", "topic": "Extended parasitic cases", "pages": [18, 20, 22, 34], "page": 18, "ref": "slide-inf-18", "stem": "A 16-year-old develops severe headache, fever, vomiting, and rapidly worsening confusion five days after diving in a warm freshwater lake. Water had forcefully entered the nose. CSF contains many neutrophils, high protein, and low glucose, initially resembling bacterial meningitis. Fresh microscopy identifies motile organisms, prompting urgent reference testing and specialized therapy consultation. Which organism best explains both the nasal/olfactory exposure route and the unusually fulminant meningoencephalitic course?", "options": [{"text": "Trypanosoma brucei", "why": "Tsetse-transmitted African trypanosomiasis can enter the CNS and cause sleep-cycle disturbance, cognitive change, and meningoencephalitis."}, {"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}, {"text": "Naegleria fowleri", "why": "Naegleria causes primary amebic meningoencephalitis after contaminated water enters the nose. A neutrophilic CSF profile does not make it bacterial; fresh wet mount and specific molecular testing can identify the organism."}, {"text": "Toxoplasma gondii", "why": "A protozoan can reactivate in advanced HIV, causing multiple enhancing focal brain lesions, and is important in retinochoroiditis."}, {"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}], "answer": 2, "image": null}, {"id": "Q170", "deck": "inf", "topic": "Extended parasitic cases", "pages": [18, 35, 37], "page": 18, "ref": "slide-inf-18", "stem": "A 32-year-old who lived in an endemic region presents after a new seizure. Brain imaging shows several lesions at different stages, including a cyst with a visible scolex and calcified nodules. A household contact previously had an intestinal pork tapeworm. The patient does not eat pork and therefore initially rejects the proposed diagnosis. Which pathogen fits the imaging and explains why abstaining from pork does not exclude tissue infection acquired through fecal contamination?", "options": [{"text": "Taenia solium larvae", "why": "Human cysticercosis follows ingestion of eggs from a human carrier. It can occur without pork consumption. Larval brain cysts can be viable, inflamed, or calcified and should not be equated with a uniform pyogenic abscess."}, {"text": "Acanthamoeba species", "why": "Free-living amebas can cause keratitis and more indolent granulomatous amebic encephalitis, especially in susceptible hosts."}, {"text": "Balamuthia mandrillaris", "why": "This free-living ameba can cause granulomatous encephalitis, sometimes after skin or inhalational exposure and including immunocompetent people."}, {"text": "Echinococcus granulosus", "why": "Ingestion of eggs from a dog-associated life cycle can lead to hydatid cysts, occasionally in the brain; a hydatid cyst is not a routine pyogenic abscess."}, {"text": "Plasmodium falciparum", "why": "Severe malaria can cause cerebral disease through infected erythrocyte sequestration and microvascular dysfunction, not a typical encysted brain abscess."}], "answer": 0, "image": null}]};
